import {executarAutomaticoHml} from './cicloAutomaticoHml.ts'
import {criarHandlerWebhookWhatsApp} from './metaWebhook.ts'
import {ESCOPO_META_HML} from '../mensageria-confirmacao-hml/escopoMetaHml.ts'

type Env={get(key:string):string|undefined}
type Entrada=Record<string,unknown>
const {projeto,wabaId,phoneNumberId,appId}=ESCOPO_META_HML
export const PATH='/webhook-whatsapp-hml/piloto/webhook'
const base='https://'+projeto+'.supabase.co'
const resposta=(status:number,codigo:string)=>Response.json({codigo},{status})

function registro(valor:unknown):Entrada{
  return valor&&typeof valor==='object'&&!Array.isArray(valor)?valor as Entrada:{}
}
function escopoValido(payload:Entrada){
  return payload.object==='whatsapp_business_account'&&Array.isArray(payload.entry)&&payload.entry.length>0&&
    payload.entry.every(item=>{
      const entrada=registro(item)
      return entrada.id===wabaId&&Array.isArray(entrada.changes)&&entrada.changes.length>0&&
        entrada.changes.every(item=>{
          const alteracao=registro(item)
          return alteracao.field==='messages'&&
            registro(registro(alteracao.value).metadata).phone_number_id===phoneNumberId
        })
    })
}

export function criarReceptorHml(env:Env,requisitar:typeof fetch=fetch){
  const key=env.get('SUPABASE_SERVICE_ROLE_KEY')
  const appSecret=env.get('HML_META_APP_SECRET')
  const verify=env.get('HML_META_VERIFY_TOKEN')
  if(env.get('HML_PROJECT_REF')!==projeto||env.get('SUPABASE_URL')!==base||
     env.get('HML_META_TEST_APP_ID')!==appId||env.get('HML_META_TEST_WABA_ID')!==wabaId||
     env.get('HML_META_TEST_PHONE_NUMBER_ID')!==phoneNumberId||
     !key||!appSecret||appSecret.length<16||!verify||verify.length<24)
    return async ()=>resposta(503,'HML_CONFIGURACAO_INVALIDA')

  async function rpc(nome:'receptor_aberto'|'receber_webhook',body:Entrada){
    const r=await requisitar(base+'/rest/v1/rpc/mensageria_hml_'+nome,{
      method:'POST',redirect:'error',signal:AbortSignal.timeout(8000),
      headers:{apikey:key!,authorization:'Bearer '+key,'content-type':'application/json'},
      body:JSON.stringify(body)
    })
    if(!r.ok)throw Error('BACKEND_HML_INDISPONIVEL')
    return await r.json()===true
  }

  return async(req:Request)=>{
    if(new URL(req.url).pathname!==PATH)return resposta(404,'ROTA_NAO_PUBLICA')
    if(req.method!=='GET'&&req.method!=='POST')return resposta(405,'METODO_NAO_PERMITIDO')
    if(env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')==='true')return resposta(503,'RECEPTOR_DESABILITADO')
    if(req.method==='GET'){
      try{if(!await rpc('receptor_aberto',{}))return resposta(503,'RECEPTOR_DESABILITADO')}
      catch{return resposta(503,'BACKEND_HML_INDISPONIVEL')}
    }
    let falha:Response|undefined
    let cliquePersistido=false
    const handler=criarHandlerWebhookWhatsApp(()=>verify,()=>appSecret,async e=>{
      if(!escopoValido(e.payload)){
        falha=resposta(403,'ESCOPO_NAO_AUTORIZADO')
        throw Error('ESCOPO_NAO_AUTORIZADO')
      }
      try{
        const gravado=await rpc('receber_webhook',{
          p_payload_sha256:e.payloadSha256,p_payload:e.payload,p_classificacao:e.classificacao,p_itens:e.itens,
        })
        if(!gravado)falha=resposta(503,'RECEPTOR_DESABILITADO')
        else cliquePersistido=e.itens.some(item=>item.tipo==='mensagem_inbound'&&['button','interactive'].includes(item.tipo_mensagem??''))
      }catch{falha=resposta(503,'BACKEND_HML_INDISPONIVEL')}
      if(falha)throw Error('PERSISTENCIA_HML_INDISPONIVEL')
    },()=>{})
    const resultado=await handler(req)
    if(!falha&&resultado.ok&&cliquePersistido){
      const trabalho=executarAutomaticoHml(env,requisitar).catch(()=>console.warn({evento:'hml_ciclo_automatico',estado:'falha'}))
      const runtime=(globalThis as unknown as {EdgeRuntime?:{waitUntil(p:Promise<void>):void}}).EdgeRuntime
      if(runtime?.waitUntil)runtime.waitUntil(trabalho)
      else await trabalho
    }
    return falha??resultado
  }
}

import {executarCicloAutomatico} from './cicloAutomaticoCoreHml.js'
import {ESCOPO_META_HML} from '../mensageria-confirmacao-hml/escopoMetaHml.ts'
import {criarTransporteMetaHml,envioMetaHmlHabilitado} from '../mensageria-outbox-hml/transporteMetaHml.ts'
import {criarAdaptadorRpcOutboxHml} from '../mensageria-outbox-hml/adaptadorRpcOutboxHml.ts'
import {executarUmAgradecimentoHml} from '../mensageria-outbox-hml/orquestradorDespachoHml.ts'
type Env={get(key:string):string|undefined}
type Controle={status:string;receptor:boolean;processamento:boolean;revisao:number;envio_expira_em:string|null}
const REF=ESCOPO_META_HML.projeto
const BASE='https://'+REF+'.supabase.co'
const UUID=/^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/i
export async function executarAutomaticoHml(env:Env,requisitar:typeof fetch){
 const key=env.get('SUPABASE_SERVICE_ROLE_KEY')
 const operador=env.get('HML_OPERATOR_UUID')??''
 if(env.get('SUPABASE_URL')!==BASE||env.get('HML_PROJECT_REF')!==REF||!key||!UUID.test(operador)||env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')==='true')return
 const rpc=async(nome:'operacao'|'listar_cliques_pendentes'|'processar_clique_operacao',args:Record<string,unknown>)=>{
  const r=await requisitar(BASE+'/rest/v1/rpc/mensageria_hml_'+nome,{
   method:'POST',redirect:'error',signal:AbortSignal.timeout(12000),
   headers:{apikey:key,authorization:'Bearer '+key,'content-type':'application/json'},
   body:JSON.stringify({...args,p_operador:operador})
  })
  if(!r.ok)throw Error('RPC_HML_INDISPONIVEL')
  const data=await r.json()
  if(!data||typeof data!=='object'||Array.isArray(data))throw Error('RPC_HML_INVALIDA')
  return data
 }
 const controles=async():Promise<Controle>=>{
  const c=await rpc('operacao',{p_acao:'status',p_segundos:null})
  return env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')==='true'?{...c,receptor:false}:c
 }
 const r=await executarCicloAutomatico({
  controles,
  listar:async(limite:number)=>{
   const lista=await rpc('listar_cliques_pendentes',{p_limite:limite})
   if(lista.status!=='ok')throw Error('FILA_NAO_AUTORIZADA')
   return lista.itens
  },
  processar:async(id:string)=>await rpc('processar_clique_operacao',{p_item:id}),
  agora:Date.now,
  despachar:async(c:Controle,outboxId:string,expira:string)=>{
   // A unidade ativa e o clique novo autorizam exclusivamente este agradecimento.
   // Expiração interna limita a execução; não abre a janela de convites.
   if(!UUID.test(outboxId)||Date.parse(expira)<=Date.now()||env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')return null
   const ambiente={get(nome:string){
    if(nome==='HML_OUTBOX_SEND_EXPIRES_AT')return expira
    if(['HML_CONFIRMATION_REAL_SEND_ENABLED','HML_OUTBOX_SEND_ENABLED','HML_OUTBOX_RPC_ENABLED'].includes(nome))
     return env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true'?'false':'true'
    return env.get(nome)
   }}
   if(!envioMetaHmlHabilitado(ambiente))return null
   const transporte=criarTransporteMetaHml({ambiente,requisitar:async(url,init)=>{
    const atual=await controles()
    if(atual.status!=='ok'||!atual.receptor||!atual.processamento||atual.revisao!==c.revisao||Date.parse(expira)<=Date.now()||env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')throw Error('AUTORIZACAO_ENCERRADA')
    const corpo=JSON.parse(String(init?.body??''))
    if(corpo.type!=='text'||corpo.context?.message_id===undefined)throw Error('SOMENTE_AGRADECIMENTO_HML')
    return requisitar(url,init)
   }})
   const ops=criarAdaptadorRpcOutboxHml({ambiente,requisitar,enviar:async(body)=>transporte(body)})
   if(!ops.configurado())return null
   const escopado={...ops,listar:async(_limite:number)=>{
     const fila=await ops.listar(10)
     const itens=fila.itens.filter(id=>id===outboxId)
     return {status:fila.status,itens,quantidade:itens.length}
   }}
   return executarUmAgradecimentoHml({projeto:REF,operadorId:operador,permitidoE164:env.get('HML_TEST_RECIPIENT_E164')??'',envioHabilitado:true,autorizacaoExpiraIso:expira,agora:()=>new Date(),chaveAleatoria:()=>crypto.randomUUID()},escopado)
  }
 })
 console.info({evento:'hml_ciclo_automatico_v46',estado:r.estado,processados:r.processados,erros:r.erros,despachos:r.despachos.map(d=>({estado:d.estado,codigo:d.codigo,aceitosMeta:d.aceitosMeta})),aceites_meta:r.despachos.reduce((total,d)=>total+(d.aceitosMeta??0),0)})
}

export async function executarCicloAutomatico(ops){
 const inicial=await ops.controles();
 const habilitado=x=>x?.status==='ok'&&x.receptor===true&&x.processamento===true&&Number.isSafeInteger(x.revisao);
 const mesmo=x=>habilitado(x)&&x.revisao===inicial.revisao;
 const uuid=id=>typeof id==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);
 if(!habilitado(inicial))return {estado:'desativado',processados:0,erros:0,despachos:[]};
 const ids=await ops.listar(5);
 if(!Array.isArray(ids)||ids.length>5||!ids.every(uuid))throw Error('FILA_INVALIDA');
 let processados=0,erros=0;
 const despachos=[];
 for(const id of new Set(ids)){
  if(!mesmo(await ops.controles()))return {estado:'controle_alterado',processados,erros,despachos};
  try{
   const r=await ops.processar(id);
   if(r?.status==='desativado')return {estado:'desativado',processados,erros,despachos};
   if(!['confirmado','remarcacao_pendente','ja_processado','ignorado','rejeitado','expirado','conflito','ja_resolvido'].includes(r?.status)){erros++;continue}
   processados++;
   if(r.status!=='confirmado')continue;
   if(!uuid(r.outboxId)||!['pronto','ja_preparado'].includes(r.preparo_outbox)){erros++;continue}
   const atual=await ops.controles();
   if(!mesmo(atual))return {estado:'controle_alterado',processados,erros,despachos};
   const instante=ops.agora();
   if(!Number.isFinite(instante)){erros++;continue}
   const expira=new Date(instante+120000).toISOString();
   const d=await ops.despachar(atual,r.outboxId,expira);
   despachos.push(d??{estado:'bloqueado',codigo:'CONFIGURACAO_INDISPONIVEL',aceitosMeta:0});
  }catch{erros++}
 }
 return {estado:erros?'parcial':'concluido',processados,erros,despachos};
}

/**
 * Transporte para um único agradecimento HML WhatsApp Cloud API.
 *
 * É um adaptador isolado para testes com fetch injetado:
 * NÃO é importado pela Edge mensageria-outbox-hml v1.
 * NÃO registra corpo, token, telefone, headers ou resposta bruta em logs.
 * SEM retry automático. A decisão de reservar/finalizar pertence à outbox.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {NOME_TEMPLATE_HML} from '../mensageria-confirmacao-hml/solicitacaoTemplateMeta.ts'
import type {CorpoTemplateMeta} from '../mensageria-confirmacao-hml/templateConfirmacao.ts'
import type {EnvioTextoMeta} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

import { ESCOPO_META_HML } from '../mensageria-confirmacao-hml/escopoMetaHml.ts'

const HML=ESCOPO_META_HML.projeto
const HML_URL='https://'+HML+'.supabase.co'
const META_PHONE_HML=ESCOPO_META_HML.phoneNumberId
const GRAPH='https://graph.facebook.com/'+ESCOPO_META_HML.versaoGraph+'/'+META_PHONE_HML+'/messages'
const DESTINO=/^55[1-9][0-9]{9,10}$/

export type AmbienteMetaHml={get:(name:string)=>string|undefined}
export type ResultadoMetaHml={httpStatus:number;wamid:string|null}
export type OpcoesTransporteHml={
  ambiente:AmbienteMetaHml
  requisitar?:(url:string,init:RequestInit)=>Promise<Response>
  agora?:()=>number
}

function permitido(env:AmbienteMetaHml,agora:number):{destino:string;token:string}|null{
  if(env.get('HML_PROJECT_REF')!==HML||
     env.get('SUPABASE_URL')!==HML_URL||
     env.get('HML_CONFIRMATION_REAL_SEND_ENABLED')!=='true'||
     env.get('HML_META_TEST_WABA_ID')!==ESCOPO_META_HML.wabaId||
     env.get('HML_META_TEST_APP_ID')!==ESCOPO_META_HML.appId||
     env.get('HML_META_TEST_PHONE_NUMBER_ID')!==META_PHONE_HML||
     env.get('HML_OUTBOX_SEND_ENABLED')!=='true')return null
  const fim=Date.parse(env.get('HML_OUTBOX_SEND_EXPIRES_AT')??'')
  if(!Number.isFinite(agora)||!Number.isFinite(fim)||
     fim<=agora||fim-agora>180_000)return null
  const destino=env.get('HML_TEST_RECIPIENT_E164')??''
  const token=env.get('HML_META_TEST_ACCESS_TOKEN')??''
  if(!DESTINO.test(destino)||token.length<32||token.length>4096||
     /[\r\n]/.test(token))return null
  return {destino,token}
}
export function envioMetaHmlHabilitado(env:AmbienteMetaHml):boolean{
  return permitido(env,Date.now())!==null
}
function corpoValido(c:EnvioTextoMeta,destino:string):boolean {
  return c?.messaging_product==='whatsapp'&&
    c.recipient_type==='individual'&&
    c.to===destino&&c.type==='text'&&
    c.text?.preview_url===false&&
    typeof c.text?.body==='string'&&
    c.text.body.trim().length>=1&&c.text.body.length<=4096&&
    typeof c.context?.message_id==='string'&&
    wamidValidoHml(c.context.message_id)
}

export function criarTransporteMetaHml({ambiente,requisitar=fetch,agora=Date.now}:OpcoesTransporteHml){
  return async (body:EnvioTextoMeta|CorpoTemplateMeta):Promise<ResultadoMetaHml>=>{
    const cfg=permitido(ambiente,agora())
    if(!cfg)throw new Error('ENVIO_META_HML_NAO_AUTORIZADO')
    if(body?.type==='template'
      ? body.to!==cfg.destino||body.messaging_product!=='whatsapp'||
        body.template.name!==NOME_TEMPLATE_HML||body.template.language.code!=='pt_BR'
      : !corpoValido(body,cfg.destino))throw new Error('MENSAGEM_META_HML_INVALIDA')
    // Confere a janela uma segunda vez imediatamente antes do POST.
    const atual=permitido(ambiente,agora())
    if(!atual||atual.destino!==cfg.destino||atual.token!==cfg.token)
      throw new Error('AUTORIZACAO_EXPIRADA')
    let res:Response
    try{
      res=await requisitar(GRAPH,{
        method:'POST',redirect:'error',signal:AbortSignal.timeout(12000),
        headers:{authorization:'Bearer '+cfg.token,'content-type':'application/json'},
        body:JSON.stringify(body)
      })
    }catch{
      // A Meta pode ter aceitado antes de ocorrer timeout, queda de rede
      // ou redirecionamento. É proibido repetir automaticamente a chamada.
      throw new Error('META_RESPOSTA_INDETERMINADA')
    }
    if(!Number.isInteger(res.status)||res.status<200||res.status>599)
      return {httpStatus:503,wamid:null}
    if(res.status<200||res.status>=300)return {httpStatus:res.status,wamid:null}
    let parsed:unknown
    try{parsed=await res.json()}catch{
      return {httpStatus:res.status,wamid:null}
    }
    if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))
      return {httpStatus:res.status,wamid:null}
    const response=parsed as {
      messaging_product?:unknown
      contacts?:{input?:unknown;wa_id?:unknown}[]
      messages?:{id?:unknown}[]
    }
    const id=response.messages?.[0]?.id
    // contacts[].wa_id pode ser diferente da entrada (nono dígito BR).
    // contacts[].input, quando presente, precisa refletir o destino pedido.
    if(response.messaging_product!=='whatsapp'||
       (Array.isArray(response.contacts)&&
         (response.contacts[0]?.input!==cfg.destino))||
       !Array.isArray(response.messages)||
       typeof id!=='string'||!wamidValidoHml(id))
      return {httpStatus:res.status,wamid:null}
    return {httpStatus:res.status,wamid:id}
  }
}

// Preserva o ID opaco da Meta, inclusive o padding Base64 no fim.
export function wamidValidoHml(valor:unknown):valor is string{
  return typeof valor==='string'&&valor.length>=10&&valor.length<=300&&
    /^wamid\.[A-Za-z0-9+/_.-]{4,}={0,2}$/.test(valor)&&!/[\r\n]/.test(valor)
}

/**
 * Solicitação de TEMPLATE Meta (utility) — preparação sem envio.
 * Deve ser revisado no Gerenciador do WhatsApp/Meta antes de submissão.
 * A posição dos botões deve coincidir com o payload de envio:
 *   0 = Confirmar; 1 = Remarcar.
 * NÃO submete nada à API, NÃO cria template por conta própria.
 */
export type TemplateParaAprovacao = {
  name:string
  language:'pt_BR'
  category:'UTILITY'
  parameter_format:'POSITIONAL'
  components:Array<
    {type:'BODY';text:string;example:{body_text:string[][]}} |
    {type:'BUTTONS';buttons:Array<{type:'QUICK_REPLY';text:string}>}
  >
}
export const NOME_TEMPLATE_HML='kaza_confirmacao_agendamento_hml'
export function prepararSolicitacaoTemplateMeta():TemplateParaAprovacao {
  return {
    name:NOME_TEMPLATE_HML,
    language:'pt_BR',
    category:'UTILITY',
    parameter_format:'POSITIONAL',
    components:[
      {type:'BODY',
        text:'Olá, {{1}}! 🐾\n\nO banho de {{2}} está agendado para {{3}} às {{4}} na KAZA PET.\n\nPodemos confirmar esse horário?',
        example:{body_text:[['Mariana','Thor','24/11/2026','09:00']]}},
      {type:'BUTTONS',buttons:[
        {type:'QUICK_REPLY',text:'Confirmar'},
        {type:'QUICK_REPLY',text:'Remarcar'}
      ]}
    ]
  }
}

/**
 * KAZA PET • adapter RPC da outbox de agradecimentos HML.
 *
 * APENAS para execução injetada/testes. NÃO importado na Edge publicada.
 * Sem chamadas de Graph API, sem agendamento, sem acesso do navegador.
 * Nenhum método acessa a rede quando HML_OUTBOX_RPC_ENABLED !== 'true'.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import type {OperacoesDespachoHml} from './orquestradorDespachoHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const BASE='https://'+REF+'.supabase.co'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const E164=/^\+55[1-9][0-9]{9,10}$/
const ESTADOS_RESERVA=new Set([
 'reservado','ja_reservado','nao_pronto','agenda_invalida',
 'janela_inbound_indisponivel','outro'
])
const ESTADOS_FINAL=new Set(['aceito_meta','recusado_meta','indeterminado'])
const CODIGO=/^[A-Z][A-Z0-9_]{1,63}$/
const RPCS={
  listar:'mensageria_hml_outbox_listar_pendentes',
  reservar:'mensageria_hml_outbox_reservar',
  contexto:'mensageria_hml_outbox_contexto',
  finalizar:'mensageria_hml_outbox_finalizar'
} as const
type Env={get:(nome:string)=>string|undefined}
type Fetch=(url:string,init:RequestInit)=>Promise<Response>
type Envio=OperacoesDespachoHml['enviar']

export type ConfigAdaptadorRpcHml={
  ambiente:Env
  requisitar:Fetch // obrigatório: teste sempre injetado, sem fallback implícito
  enviar:Envio // transporte injetado; não importamos Meta aqui
}
export type RpcOutboxHml=OperacoesDespachoHml & {
  /** Retorna apenas se o ambiente indica HML e a flag de RPC está ligada */
  configurado:()=>boolean
}
export function criarAdaptadorRpcOutboxHml({
  ambiente,requisitar,enviar
}:ConfigAdaptadorRpcHml):RpcOutboxHml{
  const permitido=()=>{
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')??''
    const operator=ambiente.get('HML_OPERATOR_UUID')??''
    return ambiente.get('SUPABASE_URL')===BASE&&
      ambiente.get('HML_PROJECT_REF')===REF&&
      ambiente.get('HML_OUTBOX_RPC_ENABLED')==='true'&&
      secret.length>=32&&secret.length<=8192&&!/[\r\n]/.test(secret)&&
      UUID.test(operator)&&typeof requisitar==='function'&&
      typeof enviar==='function'
  }
  const rpc=async (
    acao:keyof typeof RPCS, corpo:Record<string,unknown>
  ):Promise<Record<string,unknown>>=>{
    if(!permitido())throw Error('RPC_HML_DESATIVADA')
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')!
    let resposta:Response
    try {
      resposta=await requisitar(BASE+'/rest/v1/rpc/'+RPCS[acao],{
        method:'POST',redirect:'error',
        headers:{
          apikey:secret,authorization:'Bearer '+secret,
          'content-type':'application/json'
        },
        body:JSON.stringify(corpo),
        signal:AbortSignal.timeout(12000)
      })
    }catch{throw Error('RPC_HML_RESPOSTA_INDISPONIVEL')}
    if(!resposta.ok)throw Error('RPC_HML_REJEITADA')
    let data:unknown
    try{data=await resposta.json()}catch{
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    }
    if(!data||typeof data!=='object'||Array.isArray(data))
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    return data as Record<string,unknown>
  }
  const autorizado=(id:string)=>UUID.test(id)&&
    id===ambiente.get('HML_OPERATOR_UUID')
  return {
    configurado:permitido,
    async listar(limite){
      if(!Number.isInteger(limite)||limite<1||limite>10)
        throw Error('LIMITE_RPC_INVALIDO')
      const op=ambiente.get('HML_OPERATOR_UUID')??''
      if(!autorizado(op))throw Error('OPERADOR_RPC_INVALIDO')
      const r=await rpc('listar',{p_operador:op,p_limite:limite})
      if(r.status!=='ok'||!Array.isArray(r.itens)||
         typeof r.quantidade!=='number'||!Number.isInteger(r.quantidade)||
         r.quantidade!==r.itens.length||
         r.itens.length>limite||
         !r.itens.every(id=>typeof id==='string'&&UUID.test(id)))
        throw Error('FILA_RPC_INCONSISTENTE')
      return {status:'ok',itens:r.itens,quantidade:r.quantidade as number}
    },
    async reservar({outboxId,chave,operadorId}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId))
        throw Error('RESERVA_RPC_INVALIDA')
      const r=await rpc('reservar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId
      })
      if(typeof r.status!=='string'||!ESTADOS_RESERVA.has(r.status))
        throw Error('RESERVA_RPC_INDETERMINADA')
      return {status:r.status as Awaited<ReturnType<OperacoesDespachoHml['reservar']>>['status']}
    },
    async contexto({p_outbox,p_chave,p_operador,p_destinatario_permitido}){
      if(!UUID.test(p_outbox)||!UUID.test(p_chave)||
        !autorizado(p_operador)||!E164.test(p_destinatario_permitido)||
        p_destinatario_permitido!=='+'
          +(ambiente.get('HML_TEST_RECIPIENT_E164')??''))
        throw Error('CONTEXTO_RPC_NAO_AUTORIZADO')
      const resposta=await rpc('contexto',{
        p_outbox,p_chave,p_operador,p_destinatario_permitido
      })
      if(typeof resposta.status!=='string')
        throw Error('CONTEXTO_RPC_INVALIDO')
      return resposta
    },
    async finalizar({outboxId,chave,operadorId,resultado,wamid,codigo}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId)||
        !ESTADOS_FINAL.has(resultado))
        throw Error('FINALIZACAO_RPC_INVALIDA')
      if(resultado==='aceito_meta'){
        if(typeof wamid!=='string'||!wamidValidoHml(wamid)||codigo!==null)
          throw Error('ACEITE_RPC_INVALIDO')
      }else{
        if(wamid!==null||typeof codigo!=='string'||!CODIGO.test(codigo))
          throw Error('MOTIVO_RPC_INVALIDO')
      }
      const r=await rpc('finalizar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId,
        p_resultado:resultado,p_wamid:wamid,p_codigo:codigo
      })
      if(typeof r.status!=='string'||r.status.length>80)
        throw Error('FINALIZACAO_RPC_RESPOSTA_INVALIDA')
      return {status:r.status}
    },
    async enviar(corpo){
      if(!permitido())throw Error('RPC_HML_DESATIVADA')
      return enviar(corpo)
    }
  }
}

/**
 * KAZA PET • Mensageria • HML
 * Plano de despacho da outbox: composição de RPCs autoritativas e transportador injetado.
 *
 * NÃO IMPORTADO pela Edge publicada. NÃO FAZ rede diretamente.
 * Nunca aceitar parâmetros comerciais, telefone ou texto do navegador.
 * Ativar somente após revisão e homologação E2E de um envio Meta real.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {
  montarRespostaDaOutbox,
  type ConsultarContexto,
} from '../mensageria-confirmacao-hml/contextoOutboxBackendHml.ts'
import type {
  EnvioTextoMeta,
} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const DESTINO=/^55[1-9][0-9]{9,10}$/
type EstadoReserva='reservado'|'ja_reservado'|'nao_pronto'|'agenda_invalida'|'janela_inbound_indisponivel'|'outro'
type Finalizacao='aceito_meta'|'recusado_meta'|'indeterminado'

export type ConfigDespachoHml={
  projeto:string
  operadorId:string
  permitidoE164:string // Secret do servidor, sem '+'
  envioHabilitado:boolean
  autorizacaoExpiraIso:string|null
  agora:()=>Date
  chaveAleatoria:()=>string
}
export type OperacoesDespachoHml={
  listar(limite:number):Promise<{status:string;itens:unknown[];quantidade:number}>
  reservar(input:{outboxId:string;chave:string;operadorId:string}):Promise<{status:EstadoReserva}>
  contexto:ConsultarContexto
  enviar(corpo:EnvioTextoMeta):Promise<{httpStatus:number;wamid?:string|null}>
  finalizar(input:{
    outboxId:string;chave:string;operadorId:string;
    resultado:Finalizacao;wamid:string|null;codigo:string|null
  }):Promise<{status:string}>
}
export type ResultadoDespachoHml={
  estado:'bloqueado'|'fila_vazia'|'concorrencia'|'preparo_bloqueado'|
    'indeterminado'|'recusado'|'aceito'|'aceito_sem_registro'
  codigo:string
  aceitosMeta:number
  entregues:number
}

function validacao(cfg:ConfigDespachoHml):boolean{
  const t=cfg.agora().getTime()
  const expira=cfg.autorizacaoExpiraIso?Date.parse(cfg.autorizacaoExpiraIso):NaN
  return cfg.projeto===REF&&cfg.envioHabilitado===true&&UUID.test(cfg.operadorId)&&
    DESTINO.test(cfg.permitidoE164)&&Number.isFinite(t)&&Number.isFinite(expira)&&
    expira>t&&expira-t<=180000
}
export async function executarUmAgradecimentoHml(
  cfg:ConfigDespachoHml,ops:OperacoesDespachoHml
):Promise<ResultadoDespachoHml>{
  const resultado=(estado:ResultadoDespachoHml['estado'],codigo:string):ResultadoDespachoHml=>
    ({estado,codigo,aceitosMeta:0,entregues:0})
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_DE_ENVIO_AUSENTE')
  let itens:unknown[]
  try{
    const fila=await ops.listar(1)
    if(fila.status!=='ok'||!Array.isArray(fila.itens)||
       fila.itens.length>1||fila.quantidade!==fila.itens.length||
       !fila.itens.every(x=>typeof x==='string'&&UUID.test(x)))
      return resultado('bloqueado','FILA_INCONSISTENTE')
    itens=fila.itens
  }catch{return resultado('bloqueado','FILA_INDISPONIVEL')}
  if(itens.length===0)return resultado('fila_vazia','NENHUMA_RESPOSTA_ELEGIVEL')
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_VENCIDA')

  const outboxId=itens[0] as string
  const chave=cfg.chaveAleatoria()
  if(!UUID.test(chave))return resultado('bloqueado','CHAVE_NAO_VALIDA')
  let reservado:{status:EstadoReserva}
  try{
    reservado=await ops.reservar({outboxId,chave,operadorId:cfg.operadorId})
  }catch{return resultado('bloqueado','RESERVA_NAO_CONFIRMADA')}
  if(reservado.status!=='reservado')
    return resultado('concorrencia','NENHUM_REENVIO_AUTORIZADO')

  const finalizar=async(tipo:Finalizacao,codigo:string|null,wamid:string|null)=>{
    try{
      return (await ops.finalizar({
        outboxId,chave,operadorId:cfg.operadorId,
        resultado:tipo,codigo,wamid
      })).status===tipo
    }catch{return false}
  }

  // A consulta RPC autoritativa verifica convite + webhook assinado +
  // banco/agenda + modelo publicado + clique dentro da janela Meta de 24h.
  const montado=await montarRespostaDaOutbox({
    projeto:cfg.projeto,
    outboxId,chaveTentativa:chave,operadorId:cfg.operadorId,
    destinatarioPermitidoE164:'+'+cfg.permitidoE164
  },ops.contexto)
  if(montado.status!=='pronto'){
    // Sem POST Meta. Mantém tentativa única para análise manual; não reabrir fila.
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','CONTEUDO_OU_CONTEXTO_NAO_ELEGIVEL')
  }
  if(montado.corpo.to!==cfg.permitidoE164||!validacao(cfg)){
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','AUTORIZACAO_EXPIRADA_OU_DESTINO_INCORRETO')
  }
  let meta:{httpStatus:number;wamid?:string|null}
  try{
    meta=await ops.enviar(montado.corpo)
  }catch{
    await finalizar('indeterminado','META_TIMEOUT',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  // HTTP 4xx explícito é recusa. 5xx, 2xx sem wamid e demais são incertos.
  if(Number.isInteger(meta.httpStatus)&&meta.httpStatus>=400&&meta.httpStatus<500){
    await finalizar('recusado_meta','META_HTTP_'+meta.httpStatus,null)
    return resultado('recusado','META_RECUSOU')
  }
  if(meta.httpStatus!==200&&meta.httpStatus!==201||
     !meta.wamid||!wamidValidoHml(meta.wamid)){
    await finalizar('indeterminado','META_ACEITE_INDETERMINADO',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  const salvo=await finalizar('aceito_meta',null,meta.wamid)
  if(!salvo)return resultado('aceito_sem_registro','ACEITE_META_RECONCILIACAO_MANUAL')
  return {estado:'aceito',codigo:'META_ACEITOU_NAO_E_ENTREGA',aceitosMeta:1,entregues:0}
}

/**
 * Liga RPC autoritativa ao gerador de texto; ainda SEM transporte Meta.
 *
 * Somente backend HML deve executar esta função. Os IDs e a allowlist chegam
 * do backend autenticado/secret manager, nunca do navegador.
 * A RPC SQL é restrita a service_role e exige outbox previamente reservada.
 */
import {prepararAgradecimentoHml,type ContextoRespostaHml,
  type PreparacaoRespostaHml} from './respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
type Config={
  projeto:string
  outboxId:string
  chaveTentativa:string
  operadorId:string
  destinatarioPermitidoE164:string
}
type ResultadoContexto = {status:string} & Record<string,unknown>
export type ConsultarContexto =
  (args:{p_outbox:string;p_chave:string;p_operador:string;p_destinatario_permitido:string})=>Promise<unknown>
export type ResultadoPreparado =
  | {status:'pronto'; corpo:Extract<PreparacaoRespostaHml,{status:'pronto'}>['corpo']}
  | {status:'bloqueado';codigo:string}

const CAMPOS=[
  'eventoCodigo','statusAtendimento','statusConvite','textoModelo',
  'destinatarioE164','remetenteClique','mensagemCliqueId',
  'inicioAtualIso','inicioConviteIso','cliqueRecebidoIso','agoraIso',
  'nomeTutor','nomePet','nomeEmpresa'
] as const

export async function montarRespostaDaOutbox(
  config:Config, consultar:ConsultarContexto
):Promise<ResultadoPreparado> {
  if(config.projeto!==REF ||
     !UUID.test(config.outboxId) ||
     !UUID.test(config.chaveTentativa) ||
     !UUID.test(config.operadorId) ||
     !/^\+55[0-9]{10,11}$/.test(config.destinatarioPermitidoE164))
    return {status:'bloqueado',codigo:'CONTEXTO_HML_NAO_AUTORIZADO'}
  let raw:unknown
  try{
    raw=await consultar({
      p_outbox:config.outboxId,
      p_chave:config.chaveTentativa,
      p_operador:config.operadorId,
      p_destinatario_permitido:config.destinatarioPermitidoE164
    })
  }catch{return {status:'bloqueado',codigo:'CONTEXTO_HML_INDISPONIVEL'}}
  if(!raw||typeof raw!=='object'||Array.isArray(raw))
    return {status:'bloqueado',codigo:'RESPOSTA_RPC_INVALIDA'}
  const r=raw as ResultadoContexto
  if(r.status!=='pronto')return {status:'bloqueado',codigo:'OUTBOX_NAO_ELEGIVEL'}
  if(r.modeloPublicado!==true||CAMPOS.some(k=>typeof r[k]!=='string'))
    return {status:'bloqueado',codigo:'DADOS_RPC_INVALIDOS'}
  if(r.destinatarioE164!==config.destinatarioPermitidoE164)
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  if(r.eventoCodigo!=='AGENDAMENTO_CONFIRMADO_WHATSAPP')
    return {status:'bloqueado',codigo:'EVENTO_NAO_HABILITADO'}
  const result=prepararAgradecimentoHml(r as unknown as ContextoRespostaHml)
  if(result.status!=='pronto')return result
  if(result.corpo.to!==config.destinatarioPermitidoE164.slice(1))
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  return result
}

/**
 * Mensagem de resposta no WhatsApp, montada SOMENTE com contexto obtido
 * e validado no backend. Não faz HTTP, não lê credenciais e não envia mensagens.
 *
 * Origem obrigatória dos dados no serviço futuro:
 * - outbox com estado aguardando_integracao/pronto e convite confirmado;
 * - dados da agenda/grupo/pet/tutor persistidos no banco;
 * - último clique inbound validado HMAC, associado a convite e wamid;
 * - modelo PUBLICADO e versionado, nunca um rascunho local do navegador.
 */
import {wamidValidoHml} from './validarWamidHml.ts'
export type EventoRespostaHml =
  | 'AGENDAMENTO_CONFIRMADO_WHATSAPP'
  | 'REMARCACAO_SOLICITADA_WHATSAPP'
export type ContextoRespostaHml = {
  eventoCodigo:EventoRespostaHml
  statusAtendimento:string
  statusConvite:string
  modeloPublicado:boolean
  textoModelo:string
  destinatarioE164:string
  remetenteClique:string
  mensagemCliqueId:string
  inicioAtualIso:string
  inicioConviteIso:string
  cliqueRecebidoIso:string
  agoraIso:string
  nomeTutor:string
  nomePet:string
  nomeEmpresa:string
}
export type EnvioTextoMeta = {
  messaging_product:'whatsapp'
  recipient_type:'individual'
  to:string
  type:'text'
  context:{message_id:string}
  text:{body:string;preview_url:false}
}
export type PreparacaoRespostaHml =
  | {status:'pronto';corpo:EnvioTextoMeta}
  | {status:'bloqueado';codigo:string}

const MARCADOR=/\{\{\s*([A-Z_0-9]+)\s*\}\}|\{\s*([A-Z_0-9]+)\s*\}/g
const TEXTO_TAG_INCONHECIDA=/{{[^{}]*}}/
const TELEFONE=/^\+55[1-9][0-9]{9,10}$/

function equivalenteWhatsApp(destino:string,origem:string):boolean {
  const normal=destino.slice(1)
  if(origem===normal)return true
  // A Meta pode reportar alguns celulares brasileiros sem o nono dígito.
  return normal.length===13&&normal[4]==='9'&&
    origem===normal.slice(0,4)+normal.slice(5)
}
function horarioLocal(data:Date):{dia:string;hora:string} {
  return {
    dia:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'
    }).format(data),
    hora:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'
    }).format(data),
  }
}
function limparNome(valor:string):string {
  return valor.trim().replace(/[\r\n\t\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').slice(0,80)
}

export function prepararAgradecimentoHml(c:ContextoRespostaHml):PreparacaoRespostaHml {
  if(!c.modeloPublicado||!c.textoModelo?.trim())return {status:'bloqueado',codigo:'MODELO_NAO_PUBLICADO'}
  if(!TELEFONE.test(c.destinatarioE164)||!equivalenteWhatsApp(c.destinatarioE164,c.remetenteClique))
    return {status:'bloqueado',codigo:'DESTINATARIO_NAO_CORRESPONDE'}
  if(!wamidValidoHml(c.mensagemCliqueId))
    return {status:'bloqueado',codigo:'MENSAGEM_ORIGINAL_INVALIDA'}
  const esperado=c.eventoCodigo==='AGENDAMENTO_CONFIRMADO_WHATSAPP'
    ? {atendimento:'confirmado',convite:'confirmado'}
    : {atendimento:'agendado',convite:'remarcacao_pendente'}
  if(c.statusAtendimento!==esperado.atendimento||c.statusConvite!==esperado.convite)
    return {status:'bloqueado',codigo:'ESTADO_DA_AGENDA_DIVERGENTE'}
  const inicio=Date.parse(c.inicioAtualIso),antes=Date.parse(c.inicioConviteIso)
  const clique=Date.parse(c.cliqueRecebidoIso),agora=Date.parse(c.agoraIso)
  if(![inicio,antes,clique,agora].every(Number.isFinite) || inicio!==antes || inicio<=agora)
    return {status:'bloqueado',codigo:'HORARIO_MODIFICADO_OU_INVALIDO'}
  // Margem de 3min para evitar tentar entregar já perto do fim da janela.
  if(clique>agora+60_000 || agora-clique>24*60*60_000-3*60_000)
    return {status:'bloqueado',codigo:'JANELA_24H_NAO_CONFIRMADA'}
  if(![c.nomeTutor,c.nomePet,c.nomeEmpresa].every(s=>typeof s==='string'&&s.trim()))
    return {status:'bloqueado',codigo:'DADOS_INCOMPLETOS'}
  const {dia,hora}=horarioLocal(new Date(inicio))
  const tags:Record<string,string>={
    NOME_TUTOR:limparNome(c.nomeTutor),NOME_PET:limparNome(c.nomePet),
    NOME_EMPRESA:limparNome(c.nomeEmpresa),
    DATA_AGENDAMENTO:dia,HORARIO_AGENDAMENTO:hora,
  }
  let desconhecida=false
  const texto=c.textoModelo.replace(MARCADOR,(_match,keyDuplo:string|undefined,keySimples:string|undefined)=>{
    const key=keyDuplo??keySimples??''
    if(!Object.hasOwn(tags,key)){desconhecida=true;return ''}
    return tags[key]
  }).trim()
  if(desconhecida||TEXTO_TAG_INCONHECIDA.test(texto)||!texto||texto.length>4096)
    return {status:'bloqueado',codigo:'MODELO_TAG_INVALIDA'}
  if(c.eventoCodigo==='REMARCACAO_SOLICITADA_WHATSAPP' &&
    /https?:\/\//i.test(texto))
    return {status:'bloqueado',codigo:'LINK_AUTOATENDIMENTO_INDISPONIVEL'}
  return {status:'pronto',corpo:{
    messaging_product:'whatsapp',recipient_type:'individual',
    to:c.destinatarioE164.slice(1),
    type:'text',context:{message_id:c.mensagemCliqueId},
    text:{body:texto,preview_url:false}
  }}
}

type JsonObject = Record<string, unknown>

export type WhatsAppWebhookEvent =
  | { kind: 'status'; status: 'sent' | 'delivered' | 'read' | 'failed'; messageId?: string; occurredAt?: string; raw: JsonObject }
  | { kind: 'message'; messageId?: string; messageType?: string; occurredAt?: string; raw: JsonObject }

export type WebhookParseResult = {
  accepted: boolean
  events: readonly WhatsAppWebhookEvent[]
  reason?: 'invalid_root' | 'unsupported_object' | 'no_supported_events'
}

export type ItemPersistenciaWebhook = {
  dedupe_key: string
  tipo: 'status' | 'mensagem_inbound'
  mensagem_externa_id?: string
  status_meta?: 'sent' | 'delivered' | 'read' | 'failed'
  tipo_mensagem?: string
  ocorrido_at?: string
}

export type EntradaPersistenciaWebhook = {
  payloadSha256: string
  payload: JsonObject
  classificacao: 'processavel' | 'irrelevante' | 'nao_suportado'
  itens: readonly ItemPersistenciaWebhook[]
}

type VerifyToken = () => string | undefined
type AppSecret = () => string | undefined
export type PersistirWebhook = (entrada: EntradaPersistenciaWebhook) => Promise<unknown>
export type CodigoOperacional =
  | 'SIGNATURE_HEADER_MISSING'
  | 'SIGNATURE_FORMAT_INVALID'
  | 'APP_SECRET_MISSING'
  | 'SIGNATURE_MISMATCH'
  | 'SIGNATURE_OK'
  | 'BODY_TOO_LARGE'
  | 'PERSISTENCE_OK'
  | 'PERSISTENCE_ERROR'
type RegistrarOperacao = (codigo: CodigoOperacional) => void

const STATUS_ACCEPTED = new Set(['sent', 'delivered', 'read', 'failed'])
export const MAX_WEBHOOK_BODY_BYTES = 1024 * 1024
export const MAX_WEBHOOK_DRAIN_BYTES = 2 * 1024 * 1024
export const WEBHOOK_DRAIN_TIMEOUT_MS = 500
export const MAX_WEBHOOK_DRAIN_CHUNKS = 4096

export type ResultadoDrenagem = 'eof' | 'limite' | 'timeout' | 'erro'
type OpcoesDrenagem = { maxBytes?: number; timeoutMs?: number }

function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8' },
  })
}

function text(status: number, body: string): Response {
  return new Response(body, { status, headers: { 'content-type': 'text/plain; charset=utf-8' } })
}

function object(value: unknown): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function stringValue(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined
}

function timestampMeta(value: unknown): string | undefined {
  const raw = stringValue(value)
  if (!raw || !/^\d+$/.test(raw)) return undefined
  const date = new Date(Number(raw) * 1000)
  return Number.isNaN(date.getTime()) ? undefined : date.toISOString()
}

function assinaturaHex(value: string | null): Uint8Array | null {
  if (!value || !/^sha256=[0-9a-f]{64}$/i.test(value)) return null
  const bytes = new Uint8Array(32)
  for (let indice = 0; indice < bytes.length; indice += 1) bytes[indice] = Number.parseInt(value.slice(7 + indice * 2, 9 + indice * 2), 16)
  return bytes
}

function contentLengthExcedeLimite(value: string | null): boolean {
  if (!value || !/^\d+$/.test(value)) return false
  return BigInt(value) > BigInt(MAX_WEBHOOK_BODY_BYTES)
}

function cancelarLeitura(reader: ReadableStreamDefaultReader<Uint8Array>, motivo: string): void {
  try {
    void reader.cancel(motivo).catch(() => undefined)
  } catch {
    // O request ja e invalido; falha de cancelamento nao muda o 413.
  }
}

async function drenarReaderControlado(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  opcoes: OpcoesDrenagem = {},
): Promise<ResultadoDrenagem> {
  const maxBytes = opcoes.maxBytes ?? MAX_WEBHOOK_DRAIN_BYTES
  const timeoutMs = opcoes.timeoutMs ?? WEBHOOK_DRAIN_TIMEOUT_MS
  const expirou = Symbol('DRAIN_TIMEOUT')
  let timer: ReturnType<typeof setTimeout> | undefined
  const timeout = new Promise<typeof expirou>((resolve) => {
    timer = setTimeout(() => resolve(expirou), timeoutMs)
  })
  let descartados = 0
  let chunksLidos = 0
  const deadline = performance.now() + timeoutMs

  try {
    while (descartados < maxBytes) {
      if (performance.now() >= deadline) {
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_TIMEOUT')
        return 'timeout'
      }
      if (chunksLidos >= MAX_WEBHOOK_DRAIN_CHUNKS) {
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_CHUNKS')
        return 'limite'
      }
      chunksLidos += 1
      const leitura = reader.read()
      const resultado = await Promise.race([leitura, timeout])
      if (resultado === expirou) {
        leitura.catch(() => undefined)
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_TIMEOUT')
        return 'timeout'
      }
      if (resultado.done) return 'eof'
      descartados += resultado.value.byteLength
      if (descartados >= maxBytes) {
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_LIMIT')
        return 'limite'
      }
    }
    cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_LIMIT')
    return 'limite'
  } catch {
    cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_ERROR')
    return 'erro'
  } finally {
    if (timer !== undefined) clearTimeout(timer)
  }
}

export async function descartarCorpoExcedente(
  body: ReadableStream<Uint8Array> | null,
  opcoes: OpcoesDrenagem = {},
): Promise<ResultadoDrenagem> {
  if (!body) return 'eof'
  const reader = body.getReader()
  try {
    return await drenarReaderControlado(reader, opcoes)
  } finally {
    try {
      reader.releaseLock()
    } catch {
      // Um read pendente cancelado pode manter o lock ate o runtime concluir o cancelamento.
    }
  }
}

async function lerCorpoLimitado(request: Request, opcoesDrenagem: OpcoesDrenagem): Promise<ArrayBuffer | null> {
  if (!request.body) return new ArrayBuffer(0)
  const reader = request.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      if (total + value.byteLength > MAX_WEBHOOK_BODY_BYTES) {
        await drenarReaderControlado(reader, opcoesDrenagem)
        return null
      }
      chunks.push(value)
      total += value.byteLength
    }
  } finally {
    try {
      reader.releaseLock()
    } catch {
      // O cancelamento por timeout pode concluir de forma assincrona no runtime.
    }
  }

  const body = new Uint8Array(total)
  let offset = 0
  for (const chunk of chunks) {
    body.set(chunk, offset)
    offset += chunk.byteLength
  }
  return body.buffer
}

function compararConstantTime(esquerda: Uint8Array, direita: Uint8Array): boolean {
  if (esquerda.length !== direita.length) return false
  let diferenca = 0
  for (let indice = 0; indice < esquerda.length; indice += 1) diferenca |= esquerda[indice] ^ direita[indice]
  return diferenca === 0
}

function hex(bytes: Uint8Array): string {
  return [...bytes].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

async function sha256(value: ArrayBuffer | string): Promise<string> {
  const bytes = typeof value === 'string' ? new TextEncoder().encode(value) : value
  return hex(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)))
}

function jsonCanonico(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(jsonCanonico).join(',')}]`
  if (object(value)) return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${jsonCanonico(value[key])}`).join(',')}}`
  return JSON.stringify(value) ?? 'null'
}

export async function classificarAssinaturaMeta(corpoBruto: ArrayBuffer, assinaturaRecebida: string | null, appSecret: string | undefined): Promise<CodigoOperacional> {
  if (!assinaturaRecebida) return 'SIGNATURE_HEADER_MISSING'
  const recebida = assinaturaHex(assinaturaRecebida)
  if (!recebida) return 'SIGNATURE_FORMAT_INVALID'
  if (!appSecret) return 'APP_SECRET_MISSING'
  const chave = await crypto.subtle.importKey('raw', new TextEncoder().encode(appSecret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const calculada = new Uint8Array(await crypto.subtle.sign('HMAC', chave, corpoBruto))
  return compararConstantTime(calculada, recebida) ? 'SIGNATURE_OK' : 'SIGNATURE_MISMATCH'
}

function entries(body: JsonObject): JsonObject[] {
  return Array.isArray(body.entry) ? body.entry.filter(object) : []
}

export function parseWhatsAppWebhook(body: unknown): WebhookParseResult {
  if (!object(body)) return { accepted: false, events: [], reason: 'invalid_root' }
  if (body.object !== 'whatsapp_business_account') return { accepted: true, events: [], reason: 'unsupported_object' }

  const events: WhatsAppWebhookEvent[] = []
  for (const entry of entries(body)) {
    const changes = Array.isArray(entry.changes) ? entry.changes.filter(object) : []
    for (const change of changes) {
      if (change.field !== 'messages') continue
      const value = object(change.value) ? change.value : {}
      const statuses = Array.isArray(value.statuses) ? value.statuses.filter(object) : []
      for (const status of statuses) {
        const code = stringValue(status.status)
        if (code && STATUS_ACCEPTED.has(code)) {
          events.push({
            kind: 'status',
            status: code as 'sent' | 'delivered' | 'read' | 'failed',
            messageId: stringValue(status.id),
            occurredAt: timestampMeta(status.timestamp),
            raw: status,
          })
        }
      }
      const messages = Array.isArray(value.messages) ? value.messages.filter(object) : []
      for (const message of messages) {
        events.push({
          kind: 'message',
          messageId: stringValue(message.id),
          messageType: stringValue(message.type),
          occurredAt: timestampMeta(message.timestamp),
          raw: message,
        })
      }
    }
  }

  return events.length > 0 ? { accepted: true, events } : { accepted: true, events: [], reason: 'no_supported_events' }
}

async function itemPersistencia(event: WhatsAppWebhookEvent): Promise<ItemPersistenciaWebhook> {
  if (event.kind === 'message') {
    return {
      dedupe_key: event.messageId ? `message:${event.messageId}` : `message:sha256:${await sha256(jsonCanonico(event.raw))}`,
      tipo: 'mensagem_inbound',
      mensagem_externa_id: event.messageId,
      tipo_mensagem: event.messageType,
      ocorrido_at: event.occurredAt,
    }
  }

  return {
    dedupe_key: event.messageId
      ? `status:${event.messageId}:${event.status}:${event.occurredAt ?? 'sem-timestamp'}`
      : `status:sha256:${await sha256(jsonCanonico(event.raw))}`,
    tipo: 'status',
    mensagem_externa_id: event.messageId,
    status_meta: event.status,
    ocorrido_at: event.occurredAt,
  }
}

export function criarHandlerWebhookWhatsApp(
  getVerifyToken: VerifyToken,
  getAppSecret: AppSecret,
  persistirWebhook: PersistirWebhook,
  registrarOperacao: RegistrarOperacao = (codigo) => console.info({ evento: 'webhook_whatsapp', codigo }),
  opcoesDrenagem: OpcoesDrenagem = {},
) {
  return async (request: Request): Promise<Response> => {
    if (request.method === 'GET') {
      const url = new URL(request.url)
      const mode = url.searchParams.get('hub.mode')
      const token = url.searchParams.get('hub.verify_token')
      const challenge = url.searchParams.get('hub.challenge')
      const expected = getVerifyToken()
      if (!expected || mode !== 'subscribe' || !token || token !== expected || !challenge) return text(token && token !== expected ? 403 : 400, token && token !== expected ? 'Forbidden' : 'Bad Request')
      return text(200, challenge)
    }

    if (request.method !== 'POST') return json(405, { status: 'rejeitado', codigo: 'METODO_NAO_PERMITIDO' })
    if (!request.headers.get('content-type')?.toLowerCase().includes('application/json')) return json(415, { status: 'rejeitado', codigo: 'CONTENT_TYPE_INVALIDO' })

    const assinaturaRecebida = request.headers.get('x-hub-signature-256')
    if (!assinaturaRecebida) {
      registrarOperacao('SIGNATURE_HEADER_MISSING')
      return json(401, { status: 'rejeitado', codigo: 'ASSINATURA_INVALIDA' })
    }
    if (!assinaturaHex(assinaturaRecebida)) {
      registrarOperacao('SIGNATURE_FORMAT_INVALID')
      return json(401, { status: 'rejeitado', codigo: 'ASSINATURA_INVALIDA' })
    }
    if (contentLengthExcedeLimite(request.headers.get('content-length'))) {
      await descartarCorpoExcedente(request.body, opcoesDrenagem)
      registrarOperacao('BODY_TOO_LARGE')
      return json(413, { status: 'rejeitado', codigo: 'PAYLOAD_MUITO_GRANDE' })
    }

    const corpoBruto = await lerCorpoLimitado(request, opcoesDrenagem)
    if (!corpoBruto) {
      registrarOperacao('BODY_TOO_LARGE')
      return json(413, { status: 'rejeitado', codigo: 'PAYLOAD_MUITO_GRANDE' })
    }

    const resultadoAssinatura = await classificarAssinaturaMeta(corpoBruto, assinaturaRecebida, getAppSecret())
    registrarOperacao(resultadoAssinatura)
    if (resultadoAssinatura !== 'SIGNATURE_OK') return json(401, { status: 'rejeitado', codigo: 'ASSINATURA_INVALIDA' })

    let body: unknown
    try {
      body = JSON.parse(new TextDecoder().decode(corpoBruto))
    } catch {
      return json(400, { status: 'rejeitado', codigo: 'JSON_INVALIDO' })
    }

    const parsed = parseWhatsAppWebhook(body)
    if (!parsed.accepted || !object(body)) return json(400, { status: 'rejeitado', codigo: 'PAYLOAD_INVALIDO' })

    const classificacao = parsed.reason === 'unsupported_object'
      ? 'nao_suportado'
      : parsed.events.length > 0 ? 'processavel' : 'irrelevante'
    const itens = await Promise.all(parsed.events.map(itemPersistencia))

    try {
      await persistirWebhook({
        payloadSha256: await sha256(corpoBruto),
        payload: body,
        classificacao,
        itens,
      })
      registrarOperacao('PERSISTENCE_OK')
    } catch {
      registrarOperacao('PERSISTENCE_ERROR')
      return json(503, { status: 'rejeitado', codigo: 'PERSISTENCIA_INDISPONIVEL' })
    }

    return json(200, { status: 'aceito', eventos_reconhecidos: parsed.events.length })
  }
}

/**
 * Montagem PURA de template utilitário com 2 quick replies da Meta.
 * Exclusivamente para utilização no backend. Este módulo:
 * - não lê chaves da Meta nem faz HTTP;
 * - não envia mensagem e não cadastra convite;
 * - gera tokens criptograficamente aleatórios, que só devem ser usados
 *   na chamada Cloud API e armazenados no banco em hash SHA-256.
 *
 * Importante: os botões "Confirmar" e "Remarcar" e os parâmetros de body
 * devem coincidir com o TEMPLATE APROVADO pela Meta.
 */
export type TemplateConfirmacaoEntrada = {
  destinoE164: string
  permitidoE164: string
  templateNome: string
  idioma: 'pt_BR'
  parametros: readonly string[]
}
export type CorpoTemplateMeta = {
  messaging_product: 'whatsapp'
  to: string
  type: 'template'
  template: {
    name: string
    language:{code:'pt_BR'}
    components: Array<
      {type:'body'; parameters:Array<{type:'text';text:string}>} |
      {type:'button';sub_type:'quick_reply';index:'0'|'1';
       parameters:[{type:'payload';payload:string}]}
    >
  }
}
export type ConvitePreparadoBackend = {
  corpoApi: CorpoTemplateMeta
  segredoConfirmar: string
  segredoRemarcar: string
  hashConfirmar: string
  hashRemarcar: string
}
const TEL = /^\+55[1-9][0-9][2-9][0-9]{7,8}$/
const NOME = /^[a-z][a-z0-9_]{2,100}$/
function numeroNormalizado(valor:string){return valor.replace(/^\+/,'')}
async function sha256(s:string){
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))
  return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')
}
export async function prepararTemplateConfirmacaoHml(
  dados:TemplateConfirmacaoEntrada,
):Promise<ConvitePreparadoBackend> {
  if(!TEL.test(dados.destinoE164) ||
     numeroNormalizado(dados.destinoE164)!==numeroNormalizado(dados.permitidoE164))
    throw Error('DESTINATARIO_NAO_AUTORIZADO')
  if(!NOME.test(dados.templateNome)||dados.idioma!=='pt_BR')throw Error('TEMPLATE_INVALIDO')
  if(dados.parametros.length>8 || dados.parametros.some(p=>typeof p!=='string'||!p.trim()||p.length>255))
    throw Error('PARAMETROS_INVALIDOS')
  const segredoConfirmar='KPAG1_'+crypto.randomUUID()
  const segredoRemarcar='KPAG1_'+crypto.randomUUID()
  if(segredoConfirmar===segredoRemarcar)throw Error('ENTROPIA_INSUFICIENTE')
  const hashConfirmar=await sha256(segredoConfirmar)
  const hashRemarcar=await sha256(segredoRemarcar)
  const components:CorpoTemplateMeta['template']['components']=[]
  if(dados.parametros.length)components.push({
    type:'body',parameters:dados.parametros.map(text=>({type:'text',text}))
  })
  components.push({
    type:'button',sub_type:'quick_reply',index:'0',
    parameters:[{type:'payload',payload:segredoConfirmar}]
  },{
    type:'button',sub_type:'quick_reply',index:'1',
    parameters:[{type:'payload',payload:segredoRemarcar}]
  })
  return {
    corpoApi:{messaging_product:'whatsapp',to:numeroNormalizado(dados.destinoE164),
      type:'template',template:{name:dados.templateNome,language:{code:'pt_BR'},components}},
    segredoConfirmar,segredoRemarcar,hashConfirmar,hashRemarcar
  }
}

import {executarAutomaticoHml} from './cicloAutomaticoHml.ts'
import {criarHandlerWebhookWhatsApp} from './metaWebhook.ts'
import {ESCOPO_META_HML} from '../mensageria-confirmacao-hml/escopoMetaHml.ts'

type Env={get(key:string):string|undefined}
type Entrada=Record<string,unknown>
const {projeto,wabaId,phoneNumberId,appId}=ESCOPO_META_HML
export const PATH='/webhook-whatsapp-hml/piloto/webhook'
const base='https://'+projeto+'.supabase.co'
const resposta=(status:number,codigo:string)=>Response.json({codigo},{status})

function registro(valor:unknown):Entrada{
  return valor&&typeof valor==='object'&&!Array.isArray(valor)?valor as Entrada:{}
}
function escopoValido(payload:Entrada){
  return payload.object==='whatsapp_business_account'&&Array.isArray(payload.entry)&&payload.entry.length>0&&
    payload.entry.every(item=>{
      const entrada=registro(item)
      return entrada.id===wabaId&&Array.isArray(entrada.changes)&&entrada.changes.length>0&&
        entrada.changes.every(item=>{
          const alteracao=registro(item)
          return alteracao.field==='messages'&&
            registro(registro(alteracao.value).metadata).phone_number_id===phoneNumberId
        })
    })
}

export function criarReceptorHml(env:Env,requisitar:typeof fetch=fetch){
  const key=env.get('SUPABASE_SERVICE_ROLE_KEY')
  const appSecret=env.get('HML_META_APP_SECRET')
  const verify=env.get('HML_META_VERIFY_TOKEN')
  if(env.get('HML_PROJECT_REF')!==projeto||env.get('SUPABASE_URL')!==base||
     env.get('HML_META_TEST_APP_ID')!==appId||env.get('HML_META_TEST_WABA_ID')!==wabaId||
     env.get('HML_META_TEST_PHONE_NUMBER_ID')!==phoneNumberId||
     !key||!appSecret||appSecret.length<16||!verify||verify.length<24)
    return async ()=>resposta(503,'HML_CONFIGURACAO_INVALIDA')

  async function rpc(nome:'receptor_aberto'|'receber_webhook',body:Entrada){
    const r=await requisitar(base+'/rest/v1/rpc/mensageria_hml_'+nome,{
      method:'POST',redirect:'error',signal:AbortSignal.timeout(8000),
      headers:{apikey:key!,authorization:'Bearer '+key,'content-type':'application/json'},
      body:JSON.stringify(body)
    })
    if(!r.ok)throw Error('BACKEND_HML_INDISPONIVEL')
    return await r.json()===true
  }

  return async(req:Request)=>{
    if(new URL(req.url).pathname!==PATH)return resposta(404,'ROTA_NAO_PUBLICA')
    if(req.method!=='GET'&&req.method!=='POST')return resposta(405,'METODO_NAO_PERMITIDO')
    if(env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')==='true')return resposta(503,'RECEPTOR_DESABILITADO')
    if(req.method==='GET'){
      try{if(!await rpc('receptor_aberto',{}))return resposta(503,'RECEPTOR_DESABILITADO')}
      catch{return resposta(503,'BACKEND_HML_INDISPONIVEL')}
    }
    let falha:Response|undefined
    let cliquePersistido=false
    const handler=criarHandlerWebhookWhatsApp(()=>verify,()=>appSecret,async e=>{
      if(!escopoValido(e.payload)){
        falha=resposta(403,'ESCOPO_NAO_AUTORIZADO')
        throw Error('ESCOPO_NAO_AUTORIZADO')
      }
      try{
        const gravado=await rpc('receber_webhook',{
          p_payload_sha256:e.payloadSha256,p_payload:e.payload,p_classificacao:e.classificacao,p_itens:e.itens,
        })
        if(!gravado)falha=resposta(503,'RECEPTOR_DESABILITADO')
        else cliquePersistido=e.itens.some(item=>item.tipo==='mensagem_inbound'&&['button','interactive'].includes(item.tipo_mensagem??''))
      }catch{falha=resposta(503,'BACKEND_HML_INDISPONIVEL')}
      if(falha)throw Error('PERSISTENCIA_HML_INDISPONIVEL')
    },()=>{})
    const resultado=await handler(req)
    if(!falha&&resultado.ok&&cliquePersistido){
      const trabalho=executarAutomaticoHml(env,requisitar).catch(()=>console.warn({evento:'hml_ciclo_automatico',estado:'falha'}))
      const runtime=(globalThis as unknown as {EdgeRuntime?:{waitUntil(p:Promise<void>):void}}).EdgeRuntime
      if(runtime?.waitUntil)runtime.waitUntil(trabalho)
      else await trabalho
    }
    return falha??resultado
  }
}

import {executarCicloAutomatico} from './cicloAutomaticoCoreHml.js'
import {ESCOPO_META_HML} from '../mensageria-confirmacao-hml/escopoMetaHml.ts'
import {criarTransporteMetaHml,envioMetaHmlHabilitado} from '../mensageria-outbox-hml/transporteMetaHml.ts'
import {criarAdaptadorRpcOutboxHml} from '../mensageria-outbox-hml/adaptadorRpcOutboxHml.ts'
import {executarUmAgradecimentoHml} from '../mensageria-outbox-hml/orquestradorDespachoHml.ts'
type Env={get(key:string):string|undefined}
type Controle={status:string;receptor:boolean;processamento:boolean;revisao:number;envio_expira_em:string|null}
const REF=ESCOPO_META_HML.projeto
const BASE='https://'+REF+'.supabase.co'
const UUID=/^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/i
export async function executarAutomaticoHml(env:Env,requisitar:typeof fetch){
 const key=env.get('SUPABASE_SERVICE_ROLE_KEY')
 const operador=env.get('HML_OPERATOR_UUID')??''
 if(env.get('SUPABASE_URL')!==BASE||env.get('HML_PROJECT_REF')!==REF||!key||!UUID.test(operador)||env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')==='true')return
 const rpc=async(nome:'operacao'|'listar_cliques_pendentes'|'processar_clique_operacao',args:Record<string,unknown>)=>{
  const r=await requisitar(BASE+'/rest/v1/rpc/mensageria_hml_'+nome,{
   method:'POST',redirect:'error',signal:AbortSignal.timeout(12000),
   headers:{apikey:key,authorization:'Bearer '+key,'content-type':'application/json'},
   body:JSON.stringify({...args,p_operador:operador})
  })
  if(!r.ok)throw Error('RPC_HML_INDISPONIVEL')
  const data=await r.json()
  if(!data||typeof data!=='object'||Array.isArray(data))throw Error('RPC_HML_INVALIDA')
  return data
 }
 const controles=async():Promise<Controle>=>{
  const c=await rpc('operacao',{p_acao:'status',p_segundos:null})
  return env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')==='true'?{...c,receptor:false}:c
 }
 const r=await executarCicloAutomatico({
  controles,
  listar:async(limite:number)=>{
   const lista=await rpc('listar_cliques_pendentes',{p_limite:limite})
   if(lista.status!=='ok')throw Error('FILA_NAO_AUTORIZADA')
   return lista.itens
  },
  processar:async(id:string)=>(await rpc('processar_clique_operacao',{p_item:id})).status,
  agora:Date.now,
  despachar:async(c:Controle)=>{
   const expira=c.envio_expira_em
   if(!expira||env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')return null
   const ambiente={get(nome:string){
    if(nome==='HML_OUTBOX_SEND_EXPIRES_AT')return expira
    if(['HML_CONFIRMATION_REAL_SEND_ENABLED','HML_OUTBOX_SEND_ENABLED','HML_OUTBOX_RPC_ENABLED'].includes(nome))
     return env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true'?'false':'true'
    return env.get(nome)
   }}
   if(!envioMetaHmlHabilitado(ambiente))return null
   const transporte=criarTransporteMetaHml({ambiente,requisitar:async(url,init)=>{
    const atual=await controles()
    if(atual.status!=='ok'||!atual.receptor||!atual.processamento||atual.revisao!==c.revisao||atual.envio_expira_em!==expira||Date.parse(expira)<=Date.now()||env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')throw Error('AUTORIZACAO_ENCERRADA')
    return requisitar(url,init)
   }})
   const ops=criarAdaptadorRpcOutboxHml({ambiente,requisitar,enviar:async(body)=>transporte(body)})
   if(!ops.configurado())return null
   return executarUmAgradecimentoHml({projeto:REF,operadorId:operador,permitidoE164:env.get('HML_TEST_RECIPIENT_E164')??'',envioHabilitado:true,autorizacaoExpiraIso:expira,agora:()=>new Date(),chaveAleatoria:()=>crypto.randomUUID()},ops)
  }
 })
 console.info({evento:'hml_ciclo_automatico',estado:r.estado,processados:r.processados,erros:r.erros,despacho:r.despacho?.estado??null})
}

export async function executarCicloAutomatico(ops){
 const aberto=await ops.controles();
 const habilitado=x=>x?.status==='ok'&&x.receptor===true&&x.processamento===true&&Number.isSafeInteger(x.revisao);
 if(!habilitado(aberto))return {estado:'desativado',processados:0,erros:0,despacho:null};
 const ids=await ops.listar(5);
 if(!Array.isArray(ids)||ids.length>5||!ids.every(id=>typeof id==='string'&&/^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/i.test(id)))throw Error('FILA_INVALIDA');
 let processados=0,erros=0;
 for(const id of new Set(ids)){
  const atual=await ops.controles();
  if(!habilitado(atual)||atual.revisao!==aberto.revisao)return {estado:'controle_alterado',processados,erros,despacho:null};
  try{
   const r=await ops.processar(id);
   if(r==='desativado')return {estado:'desativado',processados,erros,despacho:null};
   if(['confirmado','remarcacao_pendente','ja_processado','ignorado','rejeitado','expirado','conflito','ja_resolvido'].includes(r))processados++;
   else erros++;
  }catch{erros++}
 }
 const expira=typeof aberto.envio_expira_em==='string'?Date.parse(aberto.envio_expira_em):NaN;
 const agora=ops.agora();
 let despacho=null;
 if(Number.isFinite(expira)&&expira>agora&&expira-agora<=180000&&erros===0){
  const atual=await ops.controles();
  if(habilitado(atual)&&atual.revisao===aberto.revisao&&atual.envio_expira_em===aberto.envio_expira_em)despacho=await ops.despachar(aberto);
 }
 return {estado:erros?'parcial':'concluido',processados,erros,despacho};
}

/**
 * Transporte para um único agradecimento HML WhatsApp Cloud API.
 *
 * É um adaptador isolado para testes com fetch injetado:
 * NÃO é importado pela Edge mensageria-outbox-hml v1.
 * NÃO registra corpo, token, telefone, headers ou resposta bruta em logs.
 * SEM retry automático. A decisão de reservar/finalizar pertence à outbox.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {NOME_TEMPLATE_HML} from '../mensageria-confirmacao-hml/solicitacaoTemplateMeta.ts'
import type {CorpoTemplateMeta} from '../mensageria-confirmacao-hml/templateConfirmacao.ts'
import type {EnvioTextoMeta} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

import { ESCOPO_META_HML } from '../mensageria-confirmacao-hml/escopoMetaHml.ts'

const HML=ESCOPO_META_HML.projeto
const HML_URL='https://'+HML+'.supabase.co'
const META_PHONE_HML=ESCOPO_META_HML.phoneNumberId
const GRAPH='https://graph.facebook.com/'+ESCOPO_META_HML.versaoGraph+'/'+META_PHONE_HML+'/messages'
const DESTINO=/^55[1-9][0-9]{9,10}$/

export type AmbienteMetaHml={get:(name:string)=>string|undefined}
export type ResultadoMetaHml={httpStatus:number;wamid:string|null}
export type OpcoesTransporteHml={
  ambiente:AmbienteMetaHml
  requisitar?:(url:string,init:RequestInit)=>Promise<Response>
  agora?:()=>number
}

function permitido(env:AmbienteMetaHml,agora:number):{destino:string;token:string}|null{
  if(env.get('HML_PROJECT_REF')!==HML||
     env.get('SUPABASE_URL')!==HML_URL||
     env.get('HML_CONFIRMATION_REAL_SEND_ENABLED')!=='true'||
     env.get('HML_META_TEST_WABA_ID')!==ESCOPO_META_HML.wabaId||
     env.get('HML_META_TEST_APP_ID')!==ESCOPO_META_HML.appId||
     env.get('HML_META_TEST_PHONE_NUMBER_ID')!==META_PHONE_HML||
     env.get('HML_OUTBOX_SEND_ENABLED')!=='true')return null
  const fim=Date.parse(env.get('HML_OUTBOX_SEND_EXPIRES_AT')??'')
  if(!Number.isFinite(agora)||!Number.isFinite(fim)||
     fim<=agora||fim-agora>180_000)return null
  const destino=env.get('HML_TEST_RECIPIENT_E164')??''
  const token=env.get('HML_META_TEST_ACCESS_TOKEN')??''
  if(!DESTINO.test(destino)||token.length<32||token.length>4096||
     /[\r\n]/.test(token))return null
  return {destino,token}
}
export function envioMetaHmlHabilitado(env:AmbienteMetaHml):boolean{
  return permitido(env,Date.now())!==null
}
function corpoValido(c:EnvioTextoMeta,destino:string):boolean {
  return c?.messaging_product==='whatsapp'&&
    c.recipient_type==='individual'&&
    c.to===destino&&c.type==='text'&&
    c.text?.preview_url===false&&
    typeof c.text?.body==='string'&&
    c.text.body.trim().length>=1&&c.text.body.length<=4096&&
    typeof c.context?.message_id==='string'&&
    wamidValidoHml(c.context.message_id)
}

export function criarTransporteMetaHml({ambiente,requisitar=fetch,agora=Date.now}:OpcoesTransporteHml){
  return async (body:EnvioTextoMeta|CorpoTemplateMeta):Promise<ResultadoMetaHml>=>{
    const cfg=permitido(ambiente,agora())
    if(!cfg)throw new Error('ENVIO_META_HML_NAO_AUTORIZADO')
    if(body?.type==='template'
      ? body.to!==cfg.destino||body.messaging_product!=='whatsapp'||
        body.template.name!==NOME_TEMPLATE_HML||body.template.language.code!=='pt_BR'
      : !corpoValido(body,cfg.destino))throw new Error('MENSAGEM_META_HML_INVALIDA')
    // Confere a janela uma segunda vez imediatamente antes do POST.
    const atual=permitido(ambiente,agora())
    if(!atual||atual.destino!==cfg.destino||atual.token!==cfg.token)
      throw new Error('AUTORIZACAO_EXPIRADA')
    let res:Response
    try{
      res=await requisitar(GRAPH,{
        method:'POST',redirect:'error',signal:AbortSignal.timeout(12000),
        headers:{authorization:'Bearer '+cfg.token,'content-type':'application/json'},
        body:JSON.stringify(body)
      })
    }catch{
      // A Meta pode ter aceitado antes de ocorrer timeout, queda de rede
      // ou redirecionamento. É proibido repetir automaticamente a chamada.
      throw new Error('META_RESPOSTA_INDETERMINADA')
    }
    if(!Number.isInteger(res.status)||res.status<200||res.status>599)
      return {httpStatus:503,wamid:null}
    if(res.status<200||res.status>=300)return {httpStatus:res.status,wamid:null}
    let parsed:unknown
    try{parsed=await res.json()}catch{
      return {httpStatus:res.status,wamid:null}
    }
    if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))
      return {httpStatus:res.status,wamid:null}
    const response=parsed as {
      messaging_product?:unknown
      contacts?:{input?:unknown;wa_id?:unknown}[]
      messages?:{id?:unknown}[]
    }
    const id=response.messages?.[0]?.id
    // contacts[].wa_id pode ser diferente da entrada (nono dígito BR).
    // contacts[].input, quando presente, precisa refletir o destino pedido.
    if(response.messaging_product!=='whatsapp'||
       (Array.isArray(response.contacts)&&
         (response.contacts[0]?.input!==cfg.destino))||
       !Array.isArray(response.messages)||
       typeof id!=='string'||!wamidValidoHml(id))
      return {httpStatus:res.status,wamid:null}
    return {httpStatus:res.status,wamid:id}
  }
}

// Preserva o ID opaco da Meta, inclusive o padding Base64 no fim.
export function wamidValidoHml(valor:unknown):valor is string{
  return typeof valor==='string'&&valor.length>=10&&valor.length<=300&&
    /^wamid\.[A-Za-z0-9+/_.-]{4,}={0,2}$/.test(valor)&&!/[\r\n]/.test(valor)
}

/**
 * Solicitação de TEMPLATE Meta (utility) — preparação sem envio.
 * Deve ser revisado no Gerenciador do WhatsApp/Meta antes de submissão.
 * A posição dos botões deve coincidir com o payload de envio:
 *   0 = Confirmar; 1 = Remarcar.
 * NÃO submete nada à API, NÃO cria template por conta própria.
 */
export type TemplateParaAprovacao = {
  name:string
  language:'pt_BR'
  category:'UTILITY'
  parameter_format:'POSITIONAL'
  components:Array<
    {type:'BODY';text:string;example:{body_text:string[][]}} |
    {type:'BUTTONS';buttons:Array<{type:'QUICK_REPLY';text:string}>}
  >
}
export const NOME_TEMPLATE_HML='kaza_confirmacao_agendamento_hml'
export function prepararSolicitacaoTemplateMeta():TemplateParaAprovacao {
  return {
    name:NOME_TEMPLATE_HML,
    language:'pt_BR',
    category:'UTILITY',
    parameter_format:'POSITIONAL',
    components:[
      {type:'BODY',
        text:'Olá, {{1}}! 🐾\n\nO banho de {{2}} está agendado para {{3}} às {{4}} na KAZA PET.\n\nPodemos confirmar esse horário?',
        example:{body_text:[['Mariana','Thor','24/11/2026','09:00']]}},
      {type:'BUTTONS',buttons:[
        {type:'QUICK_REPLY',text:'Confirmar'},
        {type:'QUICK_REPLY',text:'Remarcar'}
      ]}
    ]
  }
}

/**
 * KAZA PET • adapter RPC da outbox de agradecimentos HML.
 *
 * APENAS para execução injetada/testes. NÃO importado na Edge publicada.
 * Sem chamadas de Graph API, sem agendamento, sem acesso do navegador.
 * Nenhum método acessa a rede quando HML_OUTBOX_RPC_ENABLED !== 'true'.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import type {OperacoesDespachoHml} from './orquestradorDespachoHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const BASE='https://'+REF+'.supabase.co'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const E164=/^\+55[1-9][0-9]{9,10}$/
const ESTADOS_RESERVA=new Set([
 'reservado','ja_reservado','nao_pronto','agenda_invalida',
 'janela_inbound_indisponivel','outro'
])
const ESTADOS_FINAL=new Set(['aceito_meta','recusado_meta','indeterminado'])
const CODIGO=/^[A-Z][A-Z0-9_]{1,63}$/
const RPCS={
  listar:'mensageria_hml_outbox_listar_pendentes',
  reservar:'mensageria_hml_outbox_reservar',
  contexto:'mensageria_hml_outbox_contexto',
  finalizar:'mensageria_hml_outbox_finalizar'
} as const
type Env={get:(nome:string)=>string|undefined}
type Fetch=(url:string,init:RequestInit)=>Promise<Response>
type Envio=OperacoesDespachoHml['enviar']

export type ConfigAdaptadorRpcHml={
  ambiente:Env
  requisitar:Fetch // obrigatório: teste sempre injetado, sem fallback implícito
  enviar:Envio // transporte injetado; não importamos Meta aqui
}
export type RpcOutboxHml=OperacoesDespachoHml & {
  /** Retorna apenas se o ambiente indica HML e a flag de RPC está ligada */
  configurado:()=>boolean
}
export function criarAdaptadorRpcOutboxHml({
  ambiente,requisitar,enviar
}:ConfigAdaptadorRpcHml):RpcOutboxHml{
  const permitido=()=>{
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')??''
    const operator=ambiente.get('HML_OPERATOR_UUID')??''
    return ambiente.get('SUPABASE_URL')===BASE&&
      ambiente.get('HML_PROJECT_REF')===REF&&
      ambiente.get('HML_OUTBOX_RPC_ENABLED')==='true'&&
      secret.length>=32&&secret.length<=8192&&!/[\r\n]/.test(secret)&&
      UUID.test(operator)&&typeof requisitar==='function'&&
      typeof enviar==='function'
  }
  const rpc=async (
    acao:keyof typeof RPCS, corpo:Record<string,unknown>
  ):Promise<Record<string,unknown>>=>{
    if(!permitido())throw Error('RPC_HML_DESATIVADA')
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')!
    let resposta:Response
    try {
      resposta=await requisitar(BASE+'/rest/v1/rpc/'+RPCS[acao],{
        method:'POST',redirect:'error',
        headers:{
          apikey:secret,authorization:'Bearer '+secret,
          'content-type':'application/json'
        },
        body:JSON.stringify(corpo),
        signal:AbortSignal.timeout(12000)
      })
    }catch{throw Error('RPC_HML_RESPOSTA_INDISPONIVEL')}
    if(!resposta.ok)throw Error('RPC_HML_REJEITADA')
    let data:unknown
    try{data=await resposta.json()}catch{
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    }
    if(!data||typeof data!=='object'||Array.isArray(data))
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    return data as Record<string,unknown>
  }
  const autorizado=(id:string)=>UUID.test(id)&&
    id===ambiente.get('HML_OPERATOR_UUID')
  return {
    configurado:permitido,
    async listar(limite){
      if(!Number.isInteger(limite)||limite<1||limite>10)
        throw Error('LIMITE_RPC_INVALIDO')
      const op=ambiente.get('HML_OPERATOR_UUID')??''
      if(!autorizado(op))throw Error('OPERADOR_RPC_INVALIDO')
      const r=await rpc('listar',{p_operador:op,p_limite:limite})
      if(r.status!=='ok'||!Array.isArray(r.itens)||
         typeof r.quantidade!=='number'||!Number.isInteger(r.quantidade)||
         r.quantidade!==r.itens.length||
         r.itens.length>limite||
         !r.itens.every(id=>typeof id==='string'&&UUID.test(id)))
        throw Error('FILA_RPC_INCONSISTENTE')
      return {status:'ok',itens:r.itens,quantidade:r.quantidade as number}
    },
    async reservar({outboxId,chave,operadorId}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId))
        throw Error('RESERVA_RPC_INVALIDA')
      const r=await rpc('reservar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId
      })
      if(typeof r.status!=='string'||!ESTADOS_RESERVA.has(r.status))
        throw Error('RESERVA_RPC_INDETERMINADA')
      return {status:r.status as Awaited<ReturnType<OperacoesDespachoHml['reservar']>>['status']}
    },
    async contexto({p_outbox,p_chave,p_operador,p_destinatario_permitido}){
      if(!UUID.test(p_outbox)||!UUID.test(p_chave)||
        !autorizado(p_operador)||!E164.test(p_destinatario_permitido)||
        p_destinatario_permitido!=='+'
          +(ambiente.get('HML_TEST_RECIPIENT_E164')??''))
        throw Error('CONTEXTO_RPC_NAO_AUTORIZADO')
      const resposta=await rpc('contexto',{
        p_outbox,p_chave,p_operador,p_destinatario_permitido
      })
      if(typeof resposta.status!=='string')
        throw Error('CONTEXTO_RPC_INVALIDO')
      return resposta
    },
    async finalizar({outboxId,chave,operadorId,resultado,wamid,codigo}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId)||
        !ESTADOS_FINAL.has(resultado))
        throw Error('FINALIZACAO_RPC_INVALIDA')
      if(resultado==='aceito_meta'){
        if(typeof wamid!=='string'||!wamidValidoHml(wamid)||codigo!==null)
          throw Error('ACEITE_RPC_INVALIDO')
      }else{
        if(wamid!==null||typeof codigo!=='string'||!CODIGO.test(codigo))
          throw Error('MOTIVO_RPC_INVALIDO')
      }
      const r=await rpc('finalizar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId,
        p_resultado:resultado,p_wamid:wamid,p_codigo:codigo
      })
      if(typeof r.status!=='string'||r.status.length>80)
        throw Error('FINALIZACAO_RPC_RESPOSTA_INVALIDA')
      return {status:r.status}
    },
    async enviar(corpo){
      if(!permitido())throw Error('RPC_HML_DESATIVADA')
      return enviar(corpo)
    }
  }
}

/**
 * KAZA PET • Mensageria • HML
 * Plano de despacho da outbox: composição de RPCs autoritativas e transportador injetado.
 *
 * NÃO IMPORTADO pela Edge publicada. NÃO FAZ rede diretamente.
 * Nunca aceitar parâmetros comerciais, telefone ou texto do navegador.
 * Ativar somente após revisão e homologação E2E de um envio Meta real.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {
  montarRespostaDaOutbox,
  type ConsultarContexto,
} from '../mensageria-confirmacao-hml/contextoOutboxBackendHml.ts'
import type {
  EnvioTextoMeta,
} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const DESTINO=/^55[1-9][0-9]{9,10}$/
type EstadoReserva='reservado'|'ja_reservado'|'nao_pronto'|'agenda_invalida'|'janela_inbound_indisponivel'|'outro'
type Finalizacao='aceito_meta'|'recusado_meta'|'indeterminado'

export type ConfigDespachoHml={
  projeto:string
  operadorId:string
  permitidoE164:string // Secret do servidor, sem '+'
  envioHabilitado:boolean
  autorizacaoExpiraIso:string|null
  agora:()=>Date
  chaveAleatoria:()=>string
}
export type OperacoesDespachoHml={
  listar(limite:number):Promise<{status:string;itens:unknown[];quantidade:number}>
  reservar(input:{outboxId:string;chave:string;operadorId:string}):Promise<{status:EstadoReserva}>
  contexto:ConsultarContexto
  enviar(corpo:EnvioTextoMeta):Promise<{httpStatus:number;wamid?:string|null}>
  finalizar(input:{
    outboxId:string;chave:string;operadorId:string;
    resultado:Finalizacao;wamid:string|null;codigo:string|null
  }):Promise<{status:string}>
}
export type ResultadoDespachoHml={
  estado:'bloqueado'|'fila_vazia'|'concorrencia'|'preparo_bloqueado'|
    'indeterminado'|'recusado'|'aceito'|'aceito_sem_registro'
  codigo:string
  aceitosMeta:number
  entregues:number
}

function validacao(cfg:ConfigDespachoHml):boolean{
  const t=cfg.agora().getTime()
  const expira=cfg.autorizacaoExpiraIso?Date.parse(cfg.autorizacaoExpiraIso):NaN
  return cfg.projeto===REF&&cfg.envioHabilitado===true&&UUID.test(cfg.operadorId)&&
    DESTINO.test(cfg.permitidoE164)&&Number.isFinite(t)&&Number.isFinite(expira)&&
    expira>t&&expira-t<=180000
}
export async function executarUmAgradecimentoHml(
  cfg:ConfigDespachoHml,ops:OperacoesDespachoHml
):Promise<ResultadoDespachoHml>{
  const resultado=(estado:ResultadoDespachoHml['estado'],codigo:string):ResultadoDespachoHml=>
    ({estado,codigo,aceitosMeta:0,entregues:0})
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_DE_ENVIO_AUSENTE')
  let itens:unknown[]
  try{
    const fila=await ops.listar(1)
    if(fila.status!=='ok'||!Array.isArray(fila.itens)||
       fila.itens.length>1||fila.quantidade!==fila.itens.length||
       !fila.itens.every(x=>typeof x==='string'&&UUID.test(x)))
      return resultado('bloqueado','FILA_INCONSISTENTE')
    itens=fila.itens
  }catch{return resultado('bloqueado','FILA_INDISPONIVEL')}
  if(itens.length===0)return resultado('fila_vazia','NENHUMA_RESPOSTA_ELEGIVEL')
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_VENCIDA')

  const outboxId=itens[0] as string
  const chave=cfg.chaveAleatoria()
  if(!UUID.test(chave))return resultado('bloqueado','CHAVE_NAO_VALIDA')
  let reservado:{status:EstadoReserva}
  try{
    reservado=await ops.reservar({outboxId,chave,operadorId:cfg.operadorId})
  }catch{return resultado('bloqueado','RESERVA_NAO_CONFIRMADA')}
  if(reservado.status!=='reservado')
    return resultado('concorrencia','NENHUM_REENVIO_AUTORIZADO')

  const finalizar=async(tipo:Finalizacao,codigo:string|null,wamid:string|null)=>{
    try{
      return (await ops.finalizar({
        outboxId,chave,operadorId:cfg.operadorId,
        resultado:tipo,codigo,wamid
      })).status===tipo
    }catch{return false}
  }

  // A consulta RPC autoritativa verifica convite + webhook assinado +
  // banco/agenda + modelo publicado + clique dentro da janela Meta de 24h.
  const montado=await montarRespostaDaOutbox({
    projeto:cfg.projeto,
    outboxId,chaveTentativa:chave,operadorId:cfg.operadorId,
    destinatarioPermitidoE164:'+'+cfg.permitidoE164
  },ops.contexto)
  if(montado.status!=='pronto'){
    // Sem POST Meta. Mantém tentativa única para análise manual; não reabrir fila.
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','CONTEUDO_OU_CONTEXTO_NAO_ELEGIVEL')
  }
  if(montado.corpo.to!==cfg.permitidoE164||!validacao(cfg)){
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','AUTORIZACAO_EXPIRADA_OU_DESTINO_INCORRETO')
  }
  let meta:{httpStatus:number;wamid?:string|null}
  try{
    meta=await ops.enviar(montado.corpo)
  }catch{
    await finalizar('indeterminado','META_TIMEOUT',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  // HTTP 4xx explícito é recusa. 5xx, 2xx sem wamid e demais são incertos.
  if(Number.isInteger(meta.httpStatus)&&meta.httpStatus>=400&&meta.httpStatus<500){
    await finalizar('recusado_meta','META_HTTP_'+meta.httpStatus,null)
    return resultado('recusado','META_RECUSOU')
  }
  if(meta.httpStatus!==200&&meta.httpStatus!==201||
     !meta.wamid||!wamidValidoHml(meta.wamid)){
    await finalizar('indeterminado','META_ACEITE_INDETERMINADO',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  const salvo=await finalizar('aceito_meta',null,meta.wamid)
  if(!salvo)return resultado('aceito_sem_registro','ACEITE_META_RECONCILIACAO_MANUAL')
  return {estado:'aceito',codigo:'META_ACEITOU_NAO_E_ENTREGA',aceitosMeta:1,entregues:0}
}

/**
 * Liga RPC autoritativa ao gerador de texto; ainda SEM transporte Meta.
 *
 * Somente backend HML deve executar esta função. Os IDs e a allowlist chegam
 * do backend autenticado/secret manager, nunca do navegador.
 * A RPC SQL é restrita a service_role e exige outbox previamente reservada.
 */
import {prepararAgradecimentoHml,type ContextoRespostaHml,
  type PreparacaoRespostaHml} from './respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
type Config={
  projeto:string
  outboxId:string
  chaveTentativa:string
  operadorId:string
  destinatarioPermitidoE164:string
}
type ResultadoContexto = {status:string} & Record<string,unknown>
export type ConsultarContexto =
  (args:{p_outbox:string;p_chave:string;p_operador:string;p_destinatario_permitido:string})=>Promise<unknown>
export type ResultadoPreparado =
  | {status:'pronto'; corpo:Extract<PreparacaoRespostaHml,{status:'pronto'}>['corpo']}
  | {status:'bloqueado';codigo:string}

const CAMPOS=[
  'eventoCodigo','statusAtendimento','statusConvite','textoModelo',
  'destinatarioE164','remetenteClique','mensagemCliqueId',
  'inicioAtualIso','inicioConviteIso','cliqueRecebidoIso','agoraIso',
  'nomeTutor','nomePet','nomeEmpresa'
] as const

export async function montarRespostaDaOutbox(
  config:Config, consultar:ConsultarContexto
):Promise<ResultadoPreparado> {
  if(config.projeto!==REF ||
     !UUID.test(config.outboxId) ||
     !UUID.test(config.chaveTentativa) ||
     !UUID.test(config.operadorId) ||
     !/^\+55[0-9]{10,11}$/.test(config.destinatarioPermitidoE164))
    return {status:'bloqueado',codigo:'CONTEXTO_HML_NAO_AUTORIZADO'}
  let raw:unknown
  try{
    raw=await consultar({
      p_outbox:config.outboxId,
      p_chave:config.chaveTentativa,
      p_operador:config.operadorId,
      p_destinatario_permitido:config.destinatarioPermitidoE164
    })
  }catch{return {status:'bloqueado',codigo:'CONTEXTO_HML_INDISPONIVEL'}}
  if(!raw||typeof raw!=='object'||Array.isArray(raw))
    return {status:'bloqueado',codigo:'RESPOSTA_RPC_INVALIDA'}
  const r=raw as ResultadoContexto
  if(r.status!=='pronto')return {status:'bloqueado',codigo:'OUTBOX_NAO_ELEGIVEL'}
  if(r.modeloPublicado!==true||CAMPOS.some(k=>typeof r[k]!=='string'))
    return {status:'bloqueado',codigo:'DADOS_RPC_INVALIDOS'}
  if(r.destinatarioE164!==config.destinatarioPermitidoE164)
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  if(r.eventoCodigo!=='AGENDAMENTO_CONFIRMADO_WHATSAPP')
    return {status:'bloqueado',codigo:'EVENTO_NAO_HABILITADO'}
  const result=prepararAgradecimentoHml(r as unknown as ContextoRespostaHml)
  if(result.status!=='pronto')return result
  if(result.corpo.to!==config.destinatarioPermitidoE164.slice(1))
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  return result
}

/**
 * Mensagem de resposta no WhatsApp, montada SOMENTE com contexto obtido
 * e validado no backend. Não faz HTTP, não lê credenciais e não envia mensagens.
 *
 * Origem obrigatória dos dados no serviço futuro:
 * - outbox com estado aguardando_integracao/pronto e convite confirmado;
 * - dados da agenda/grupo/pet/tutor persistidos no banco;
 * - último clique inbound validado HMAC, associado a convite e wamid;
 * - modelo PUBLICADO e versionado, nunca um rascunho local do navegador.
 */
import {wamidValidoHml} from './validarWamidHml.ts'
export type EventoRespostaHml =
  | 'AGENDAMENTO_CONFIRMADO_WHATSAPP'
  | 'REMARCACAO_SOLICITADA_WHATSAPP'
export type ContextoRespostaHml = {
  eventoCodigo:EventoRespostaHml
  statusAtendimento:string
  statusConvite:string
  modeloPublicado:boolean
  textoModelo:string
  destinatarioE164:string
  remetenteClique:string
  mensagemCliqueId:string
  inicioAtualIso:string
  inicioConviteIso:string
  cliqueRecebidoIso:string
  agoraIso:string
  nomeTutor:string
  nomePet:string
  nomeEmpresa:string
}
export type EnvioTextoMeta = {
  messaging_product:'whatsapp'
  recipient_type:'individual'
  to:string
  type:'text'
  context:{message_id:string}
  text:{body:string;preview_url:false}
}
export type PreparacaoRespostaHml =
  | {status:'pronto';corpo:EnvioTextoMeta}
  | {status:'bloqueado';codigo:string}

const MARCADOR=/\{\{\s*([A-Z_0-9]+)\s*\}\}|\{\s*([A-Z_0-9]+)\s*\}/g
const TEXTO_TAG_INCONHECIDA=/{{[^{}]*}}/
const TELEFONE=/^\+55[1-9][0-9]{9,10}$/

function equivalenteWhatsApp(destino:string,origem:string):boolean {
  const normal=destino.slice(1)
  if(origem===normal)return true
  // A Meta pode reportar alguns celulares brasileiros sem o nono dígito.
  return normal.length===13&&normal[4]==='9'&&
    origem===normal.slice(0,4)+normal.slice(5)
}
function horarioLocal(data:Date):{dia:string;hora:string} {
  return {
    dia:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'
    }).format(data),
    hora:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'
    }).format(data),
  }
}
function limparNome(valor:string):string {
  return valor.trim().replace(/[\r\n\t\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').slice(0,80)
}

export function prepararAgradecimentoHml(c:ContextoRespostaHml):PreparacaoRespostaHml {
  if(!c.modeloPublicado||!c.textoModelo?.trim())return {status:'bloqueado',codigo:'MODELO_NAO_PUBLICADO'}
  if(!TELEFONE.test(c.destinatarioE164)||!equivalenteWhatsApp(c.destinatarioE164,c.remetenteClique))
    return {status:'bloqueado',codigo:'DESTINATARIO_NAO_CORRESPONDE'}
  if(!wamidValidoHml(c.mensagemCliqueId))
    return {status:'bloqueado',codigo:'MENSAGEM_ORIGINAL_INVALIDA'}
  const esperado=c.eventoCodigo==='AGENDAMENTO_CONFIRMADO_WHATSAPP'
    ? {atendimento:'confirmado',convite:'confirmado'}
    : {atendimento:'agendado',convite:'remarcacao_pendente'}
  if(c.statusAtendimento!==esperado.atendimento||c.statusConvite!==esperado.convite)
    return {status:'bloqueado',codigo:'ESTADO_DA_AGENDA_DIVERGENTE'}
  const inicio=Date.parse(c.inicioAtualIso),antes=Date.parse(c.inicioConviteIso)
  const clique=Date.parse(c.cliqueRecebidoIso),agora=Date.parse(c.agoraIso)
  if(![inicio,antes,clique,agora].every(Number.isFinite) || inicio!==antes || inicio<=agora)
    return {status:'bloqueado',codigo:'HORARIO_MODIFICADO_OU_INVALIDO'}
  // Margem de 3min para evitar tentar entregar já perto do fim da janela.
  if(clique>agora+60_000 || agora-clique>24*60*60_000-3*60_000)
    return {status:'bloqueado',codigo:'JANELA_24H_NAO_CONFIRMADA'}
  if(![c.nomeTutor,c.nomePet,c.nomeEmpresa].every(s=>typeof s==='string'&&s.trim()))
    return {status:'bloqueado',codigo:'DADOS_INCOMPLETOS'}
  const {dia,hora}=horarioLocal(new Date(inicio))
  const tags:Record<string,string>={
    NOME_TUTOR:limparNome(c.nomeTutor),NOME_PET:limparNome(c.nomePet),
    NOME_EMPRESA:limparNome(c.nomeEmpresa),
    DATA_AGENDAMENTO:dia,HORARIO_AGENDAMENTO:hora,
  }
  let desconhecida=false
  const texto=c.textoModelo.replace(MARCADOR,(_match,keyDuplo:string|undefined,keySimples:string|undefined)=>{
    const key=keyDuplo??keySimples??''
    if(!Object.hasOwn(tags,key)){desconhecida=true;return ''}
    return tags[key]
  }).trim()
  if(desconhecida||TEXTO_TAG_INCONHECIDA.test(texto)||!texto||texto.length>4096)
    return {status:'bloqueado',codigo:'MODELO_TAG_INVALIDA'}
  if(c.eventoCodigo==='REMARCACAO_SOLICITADA_WHATSAPP' &&
    /https?:\/\//i.test(texto))
    return {status:'bloqueado',codigo:'LINK_AUTOATENDIMENTO_INDISPONIVEL'}
  return {status:'pronto',corpo:{
    messaging_product:'whatsapp',recipient_type:'individual',
    to:c.destinatarioE164.slice(1),
    type:'text',context:{message_id:c.mensagemCliqueId},
    text:{body:texto,preview_url:false}
  }}
}

type JsonObject = Record<string, unknown>

export type WhatsAppWebhookEvent =
  | { kind: 'status'; status: 'sent' | 'delivered' | 'read' | 'failed'; messageId?: string; occurredAt?: string; raw: JsonObject }
  | { kind: 'message'; messageId?: string; messageType?: string; occurredAt?: string; raw: JsonObject }

export type WebhookParseResult = {
  accepted: boolean
  events: readonly WhatsAppWebhookEvent[]
  reason?: 'invalid_root' | 'unsupported_object' | 'no_supported_events'
}

export type ItemPersistenciaWebhook = {
  dedupe_key: string
  tipo: 'status' | 'mensagem_inbound'
  mensagem_externa_id?: string
  status_meta?: 'sent' | 'delivered' | 'read' | 'failed'
  tipo_mensagem?: string
  ocorrido_at?: string
}

export type EntradaPersistenciaWebhook = {
  payloadSha256: string
  payload: JsonObject
  classificacao: 'processavel' | 'irrelevante' | 'nao_suportado'
  itens: readonly ItemPersistenciaWebhook[]
}

type VerifyToken = () => string | undefined
type AppSecret = () => string | undefined
export type PersistirWebhook = (entrada: EntradaPersistenciaWebhook) => Promise<unknown>
export type CodigoOperacional =
  | 'SIGNATURE_HEADER_MISSING'
  | 'SIGNATURE_FORMAT_INVALID'
  | 'APP_SECRET_MISSING'
  | 'SIGNATURE_MISMATCH'
  | 'SIGNATURE_OK'
  | 'BODY_TOO_LARGE'
  | 'PERSISTENCE_OK'
  | 'PERSISTENCE_ERROR'
type RegistrarOperacao = (codigo: CodigoOperacional) => void

const STATUS_ACCEPTED = new Set(['sent', 'delivered', 'read', 'failed'])
export const MAX_WEBHOOK_BODY_BYTES = 1024 * 1024
export const MAX_WEBHOOK_DRAIN_BYTES = 2 * 1024 * 1024
export const WEBHOOK_DRAIN_TIMEOUT_MS = 500
export const MAX_WEBHOOK_DRAIN_CHUNKS = 4096

export type ResultadoDrenagem = 'eof' | 'limite' | 'timeout' | 'erro'
type OpcoesDrenagem = { maxBytes?: number; timeoutMs?: number }

function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8' },
  })
}

function text(status: number, body: string): Response {
  return new Response(body, { status, headers: { 'content-type': 'text/plain; charset=utf-8' } })
}

function object(value: unknown): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function stringValue(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined
}

function timestampMeta(value: unknown): string | undefined {
  const raw = stringValue(value)
  if (!raw || !/^\d+$/.test(raw)) return undefined
  const date = new Date(Number(raw) * 1000)
  return Number.isNaN(date.getTime()) ? undefined : date.toISOString()
}

function assinaturaHex(value: string | null): Uint8Array | null {
  if (!value || !/^sha256=[0-9a-f]{64}$/i.test(value)) return null
  const bytes = new Uint8Array(32)
  for (let indice = 0; indice < bytes.length; indice += 1) bytes[indice] = Number.parseInt(value.slice(7 + indice * 2, 9 + indice * 2), 16)
  return bytes
}

function contentLengthExcedeLimite(value: string | null): boolean {
  if (!value || !/^\d+$/.test(value)) return false
  return BigInt(value) > BigInt(MAX_WEBHOOK_BODY_BYTES)
}

function cancelarLeitura(reader: ReadableStreamDefaultReader<Uint8Array>, motivo: string): void {
  try {
    void reader.cancel(motivo).catch(() => undefined)
  } catch {
    // O request ja e invalido; falha de cancelamento nao muda o 413.
  }
}

async function drenarReaderControlado(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  opcoes: OpcoesDrenagem = {},
): Promise<ResultadoDrenagem> {
  const maxBytes = opcoes.maxBytes ?? MAX_WEBHOOK_DRAIN_BYTES
  const timeoutMs = opcoes.timeoutMs ?? WEBHOOK_DRAIN_TIMEOUT_MS
  const expirou = Symbol('DRAIN_TIMEOUT')
  let timer: ReturnType<typeof setTimeout> | undefined
  const timeout = new Promise<typeof expirou>((resolve) => {
    timer = setTimeout(() => resolve(expirou), timeoutMs)
  })
  let descartados = 0
  let chunksLidos = 0
  const deadline = performance.now() + timeoutMs

  try {
    while (descartados < maxBytes) {
      if (performance.now() >= deadline) {
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_TIMEOUT')
        return 'timeout'
      }
      if (chunksLidos >= MAX_WEBHOOK_DRAIN_CHUNKS) {
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_CHUNKS')
        return 'limite'
      }
      chunksLidos += 1
      const leitura = reader.read()
      const resultado = await Promise.race([leitura, timeout])
      if (resultado === expirou) {
        leitura.catch(() => undefined)
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_TIMEOUT')
        return 'timeout'
      }
      if (resultado.done) return 'eof'
      descartados += resultado.value.byteLength
      if (descartados >= maxBytes) {
        cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_LIMIT')
        return 'limite'
      }
    }
    cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_LIMIT')
    return 'limite'
  } catch {
    cancelarLeitura(reader, 'BODY_TOO_LARGE_DRAIN_ERROR')
    return 'erro'
  } finally {
    if (timer !== undefined) clearTimeout(timer)
  }
}

export async function descartarCorpoExcedente(
  body: ReadableStream<Uint8Array> | null,
  opcoes: OpcoesDrenagem = {},
): Promise<ResultadoDrenagem> {
  if (!body) return 'eof'
  const reader = body.getReader()
  try {
    return await drenarReaderControlado(reader, opcoes)
  } finally {
    try {
      reader.releaseLock()
    } catch {
      // Um read pendente cancelado pode manter o lock ate o runtime concluir o cancelamento.
    }
  }
}

async function lerCorpoLimitado(request: Request, opcoesDrenagem: OpcoesDrenagem): Promise<ArrayBuffer | null> {
  if (!request.body) return new ArrayBuffer(0)
  const reader = request.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      if (total + value.byteLength > MAX_WEBHOOK_BODY_BYTES) {
        await drenarReaderControlado(reader, opcoesDrenagem)
        return null
      }
      chunks.push(value)
      total += value.byteLength
    }
  } finally {
    try {
      reader.releaseLock()
    } catch {
      // O cancelamento por timeout pode concluir de forma assincrona no runtime.
    }
  }

  const body = new Uint8Array(total)
  let offset = 0
  for (const chunk of chunks) {
    body.set(chunk, offset)
    offset += chunk.byteLength
  }
  return body.buffer
}

function compararConstantTime(esquerda: Uint8Array, direita: Uint8Array): boolean {
  if (esquerda.length !== direita.length) return false
  let diferenca = 0
  for (let indice = 0; indice < esquerda.length; indice += 1) diferenca |= esquerda[indice] ^ direita[indice]
  return diferenca === 0
}

function hex(bytes: Uint8Array): string {
  return [...bytes].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

async function sha256(value: ArrayBuffer | string): Promise<string> {
  const bytes = typeof value === 'string' ? new TextEncoder().encode(value) : value
  return hex(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)))
}

function jsonCanonico(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(jsonCanonico).join(',')}]`
  if (object(value)) return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${jsonCanonico(value[key])}`).join(',')}}`
  return JSON.stringify(value) ?? 'null'
}

export async function classificarAssinaturaMeta(corpoBruto: ArrayBuffer, assinaturaRecebida: string | null, appSecret: string | undefined): Promise<CodigoOperacional> {
  if (!assinaturaRecebida) return 'SIGNATURE_HEADER_MISSING'
  const recebida = assinaturaHex(assinaturaRecebida)
  if (!recebida) return 'SIGNATURE_FORMAT_INVALID'
  if (!appSecret) return 'APP_SECRET_MISSING'
  const chave = await crypto.subtle.importKey('raw', new TextEncoder().encode(appSecret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const calculada = new Uint8Array(await crypto.subtle.sign('HMAC', chave, corpoBruto))
  return compararConstantTime(calculada, recebida) ? 'SIGNATURE_OK' : 'SIGNATURE_MISMATCH'
}

function entries(body: JsonObject): JsonObject[] {
  return Array.isArray(body.entry) ? body.entry.filter(object) : []
}

export function parseWhatsAppWebhook(body: unknown): WebhookParseResult {
  if (!object(body)) return { accepted: false, events: [], reason: 'invalid_root' }
  if (body.object !== 'whatsapp_business_account') return { accepted: true, events: [], reason: 'unsupported_object' }

  const events: WhatsAppWebhookEvent[] = []
  for (const entry of entries(body)) {
    const changes = Array.isArray(entry.changes) ? entry.changes.filter(object) : []
    for (const change of changes) {
      if (change.field !== 'messages') continue
      const value = object(change.value) ? change.value : {}
      const statuses = Array.isArray(value.statuses) ? value.statuses.filter(object) : []
      for (const status of statuses) {
        const code = stringValue(status.status)
        if (code && STATUS_ACCEPTED.has(code)) {
          events.push({
            kind: 'status',
            status: code as 'sent' | 'delivered' | 'read' | 'failed',
            messageId: stringValue(status.id),
            occurredAt: timestampMeta(status.timestamp),
            raw: status,
          })
        }
      }
      const messages = Array.isArray(value.messages) ? value.messages.filter(object) : []
      for (const message of messages) {
        events.push({
          kind: 'message',
          messageId: stringValue(message.id),
          messageType: stringValue(message.type),
          occurredAt: timestampMeta(message.timestamp),
          raw: message,
        })
      }
    }
  }

  return events.length > 0 ? { accepted: true, events } : { accepted: true, events: [], reason: 'no_supported_events' }
}

async function itemPersistencia(event: WhatsAppWebhookEvent): Promise<ItemPersistenciaWebhook> {
  if (event.kind === 'message') {
    return {
      dedupe_key: event.messageId ? `message:${event.messageId}` : `message:sha256:${await sha256(jsonCanonico(event.raw))}`,
      tipo: 'mensagem_inbound',
      mensagem_externa_id: event.messageId,
      tipo_mensagem: event.messageType,
      ocorrido_at: event.occurredAt,
    }
  }

  return {
    dedupe_key: event.messageId
      ? `status:${event.messageId}:${event.status}:${event.occurredAt ?? 'sem-timestamp'}`
      : `status:sha256:${await sha256(jsonCanonico(event.raw))}`,
    tipo: 'status',
    mensagem_externa_id: event.messageId,
    status_meta: event.status,
    ocorrido_at: event.occurredAt,
  }
}

export function criarHandlerWebhookWhatsApp(
  getVerifyToken: VerifyToken,
  getAppSecret: AppSecret,
  persistirWebhook: PersistirWebhook,
  registrarOperacao: RegistrarOperacao = (codigo) => console.info({ evento: 'webhook_whatsapp', codigo }),
  opcoesDrenagem: OpcoesDrenagem = {},
) {
  return async (request: Request): Promise<Response> => {
    if (request.method === 'GET') {
      const url = new URL(request.url)
      const mode = url.searchParams.get('hub.mode')
      const token = url.searchParams.get('hub.verify_token')
      const challenge = url.searchParams.get('hub.challenge')
      const expected = getVerifyToken()
      if (!expected || mode !== 'subscribe' || !token || token !== expected || !challenge) return text(token && token !== expected ? 403 : 400, token && token !== expected ? 'Forbidden' : 'Bad Request')
      return text(200, challenge)
    }

    if (request.method !== 'POST') return json(405, { status: 'rejeitado', codigo: 'METODO_NAO_PERMITIDO' })
    if (!request.headers.get('content-type')?.toLowerCase().includes('application/json')) return json(415, { status: 'rejeitado', codigo: 'CONTENT_TYPE_INVALIDO' })

    const assinaturaRecebida = request.headers.get('x-hub-signature-256')
    if (!assinaturaRecebida) {
      registrarOperacao('SIGNATURE_HEADER_MISSING')
      return json(401, { status: 'rejeitado', codigo: 'ASSINATURA_INVALIDA' })
    }
    if (!assinaturaHex(assinaturaRecebida)) {
      registrarOperacao('SIGNATURE_FORMAT_INVALID')
      return json(401, { status: 'rejeitado', codigo: 'ASSINATURA_INVALIDA' })
    }
    if (contentLengthExcedeLimite(request.headers.get('content-length'))) {
      await descartarCorpoExcedente(request.body, opcoesDrenagem)
      registrarOperacao('BODY_TOO_LARGE')
      return json(413, { status: 'rejeitado', codigo: 'PAYLOAD_MUITO_GRANDE' })
    }

    const corpoBruto = await lerCorpoLimitado(request, opcoesDrenagem)
    if (!corpoBruto) {
      registrarOperacao('BODY_TOO_LARGE')
      return json(413, { status: 'rejeitado', codigo: 'PAYLOAD_MUITO_GRANDE' })
    }

    const resultadoAssinatura = await classificarAssinaturaMeta(corpoBruto, assinaturaRecebida, getAppSecret())
    registrarOperacao(resultadoAssinatura)
    if (resultadoAssinatura !== 'SIGNATURE_OK') return json(401, { status: 'rejeitado', codigo: 'ASSINATURA_INVALIDA' })

    let body: unknown
    try {
      body = JSON.parse(new TextDecoder().decode(corpoBruto))
    } catch {
      return json(400, { status: 'rejeitado', codigo: 'JSON_INVALIDO' })
    }

    const parsed = parseWhatsAppWebhook(body)
    if (!parsed.accepted || !object(body)) return json(400, { status: 'rejeitado', codigo: 'PAYLOAD_INVALIDO' })

    const classificacao = parsed.reason === 'unsupported_object'
      ? 'nao_suportado'
      : parsed.events.length > 0 ? 'processavel' : 'irrelevante'
    const itens = await Promise.all(parsed.events.map(itemPersistencia))

    try {
      await persistirWebhook({
        payloadSha256: await sha256(corpoBruto),
        payload: body,
        classificacao,
        itens,
      })
      registrarOperacao('PERSISTENCE_OK')
    } catch {
      registrarOperacao('PERSISTENCE_ERROR')
      return json(503, { status: 'rejeitado', codigo: 'PERSISTENCIA_INDISPONIVEL' })
    }

    return json(200, { status: 'aceito', eventos_reconhecidos: parsed.events.length })
  }
}

/**
 * Montagem PURA de template utilitário com 2 quick replies da Meta.
 * Exclusivamente para utilização no backend. Este módulo:
 * - não lê chaves da Meta nem faz HTTP;
 * - não envia mensagem e não cadastra convite;
 * - gera tokens criptograficamente aleatórios, que só devem ser usados
 *   na chamada Cloud API e armazenados no banco em hash SHA-256.
 *
 * Importante: os botões "Confirmar" e "Remarcar" e os parâmetros de body
 * devem coincidir com o TEMPLATE APROVADO pela Meta.
 */
export type TemplateConfirmacaoEntrada = {
  destinoE164: string
  permitidoE164: string
  templateNome: string
  idioma: 'pt_BR'
  parametros: readonly string[]
}
export type CorpoTemplateMeta = {
  messaging_product: 'whatsapp'
  to: string
  type: 'template'
  template: {
    name: string
    language:{code:'pt_BR'}
    components: Array<
      {type:'body'; parameters:Array<{type:'text';text:string}>} |
      {type:'button';sub_type:'quick_reply';index:'0'|'1';
       parameters:[{type:'payload';payload:string}]}
    >
  }
}
export type ConvitePreparadoBackend = {
  corpoApi: CorpoTemplateMeta
  segredoConfirmar: string
  segredoRemarcar: string
  hashConfirmar: string
  hashRemarcar: string
}
const TEL = /^\+55[1-9][0-9][2-9][0-9]{7,8}$/
const NOME = /^[a-z][a-z0-9_]{2,100}$/
function numeroNormalizado(valor:string){return valor.replace(/^\+/,'')}
async function sha256(s:string){
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))
  return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')
}
export async function prepararTemplateConfirmacaoHml(
  dados:TemplateConfirmacaoEntrada,
):Promise<ConvitePreparadoBackend> {
  if(!TEL.test(dados.destinoE164) ||
     numeroNormalizado(dados.destinoE164)!==numeroNormalizado(dados.permitidoE164))
    throw Error('DESTINATARIO_NAO_AUTORIZADO')
  if(!NOME.test(dados.templateNome)||dados.idioma!=='pt_BR')throw Error('TEMPLATE_INVALIDO')
  if(dados.parametros.length>8 || dados.parametros.some(p=>typeof p!=='string'||!p.trim()||p.length>255))
    throw Error('PARAMETROS_INVALIDOS')
  const segredoConfirmar='KPAG1_'+crypto.randomUUID()
  const segredoRemarcar='KPAG1_'+crypto.randomUUID()
  if(segredoConfirmar===segredoRemarcar)throw Error('ENTROPIA_INSUFICIENTE')
  const hashConfirmar=await sha256(segredoConfirmar)
  const hashRemarcar=await sha256(segredoRemarcar)
  const components:CorpoTemplateMeta['template']['components']=[]
  if(dados.parametros.length)components.push({
    type:'body',parameters:dados.parametros.map(text=>({type:'text',text}))
  })
  components.push({
    type:'button',sub_type:'quick_reply',index:'0',
    parameters:[{type:'payload',payload:segredoConfirmar}]
  },{
    type:'button',sub_type:'quick_reply',index:'1',
    parameters:[{type:'payload',payload:segredoRemarcar}]
  })
  return {
    corpoApi:{messaging_product:'whatsapp',to:numeroNormalizado(dados.destinoE164),
      type:'template',template:{name:dados.templateNome,language:{code:'pt_BR'},components}},
    segredoConfirmar,segredoRemarcar,hashConfirmar,hashRemarcar
  }
}
